window.SYSTEM_DESIGN_CHAPTERS=[{"id":"distributed-systems-fundamentals","title":"Distributed Systems Fundamentals","intro":"Reason explicitly about consistency, availability, failure, time, delivery, and ordering.","groups":[{"title":"Consistency and availability","concepts":[{"name":"CAP theorem","summary":"During a network partition, a replicated system must choose per operation between one consistent history and a successful response from every side.","tradeoff":"Partition tolerance makes the consistency-versus-availability choice unavoidable.","visualPath":"../assets/data/system-design-visuals/6e783a960857e844.json"},{"name":"PACELC","summary":"PACELC extends CAP: during partitions choose availability or consistency; otherwise choose latency or consistency.","tradeoff":"Replica coordination costs latency even without failures.","visualPath":"../assets/data/system-design-visuals/0ec4f418029541af.json"},{"name":"Consistency models","summary":"A consistency model defines which values operations may observe under concurrency and failure.","tradeoff":"Stronger guarantees require more coordination.","visualPath":"../assets/data/system-design-visuals/8a0c3129aee155ce.json"},{"name":"Strong consistency","summary":"Strong consistency presents completed updates through one authoritative view, commonly with real-time ordering.","tradeoff":"Coordination raises latency and can reduce partition availability.","visualPath":"../assets/data/system-design-visuals/3da857874a18cdac.json"},{"name":"Linearizability","summary":"Each operation appears atomic between invocation and response while respecting real-time order.","tradeoff":"Requires critical-path coordination.","visualPath":"../assets/data/system-design-visuals/bab682edd092d8ec.json"},{"name":"Sequential consistency","summary":"All operations appear in one order that preserves each participant program order, but not necessarily wall-clock order.","tradeoff":"Weaker than linearizability and still requires global ordering.","visualPath":"../assets/data/system-design-visuals/fd9ed29a2f0a38bc.json"},{"name":"Causal consistency","summary":"Causally related operations are observed in order while concurrent operations may be observed differently.","tradeoff":"Needs causal metadata and session propagation.","visualPath":"../assets/data/system-design-visuals/a9f7ba8e7713f9e6.json"},{"name":"Eventual consistency","summary":"Replicas may diverge temporarily but converge when updates stop and messages are delivered.","tradeoff":"Clients must tolerate stale reads and conflicts.","visualPath":"../assets/data/system-design-visuals/20c10d29df9ee921.json"},{"name":"Session consistency","summary":"A client session receives guarantees such as monotonic reads and read-your-writes without imposing them globally.","tradeoff":"Constrains routing or requires session tokens.","visualPath":"../assets/data/system-design-visuals/0430461005849e5d.json"},{"name":"Read-your-writes","summary":"A session never reads a version older than its own acknowledged write.","tradeoff":"May require sticky routing or waiting for replica catch-up.","visualPath":"../assets/data/system-design-visuals/2a474eeef5f61dc2.json"},{"name":"Availability","summary":"Availability is the fraction of valid operations that complete successfully within the promised time.","tradeoff":"Higher availability needs redundancy and may weaken coordination.","visualPath":"../assets/data/system-design-visuals/fbe51d564bf2c4d2.json"},{"name":"Partition tolerance","summary":"Partition tolerance means the system has defined behavior when communication between healthy nodes is lost.","tradeoff":"Continuing on both sides risks divergence.","visualPath":"../assets/data/system-design-visuals/12b2d9282bd79f04.json"},{"name":"Quorum reads/writes","summary":"Reads contact R replicas and writes contact W of N; intersecting quorums can expose the latest accepted version.","tradeoff":"Larger quorums increase latency and reduce availability.","visualPath":"../assets/data/system-design-visuals/db94d837850cbfe4.json"},{"name":"Read repair","summary":"A read compares replica versions and asynchronously or synchronously updates stale copies.","tradeoff":"Repairs hot data but adds read cost and misses cold keys.","visualPath":"../assets/data/system-design-visuals/bed95fcaebc3933e.json"},{"name":"Anti-entropy","summary":"Background comparison and synchronization repairs divergent replicas independently of foreground reads.","tradeoff":"Consumes network, CPU, and storage bandwidth.","visualPath":"../assets/data/system-design-visuals/287c999cdb7fe0e7.json"}]},{"title":"Failure, time, and semantics","concepts":[{"name":"Gossip protocols","summary":"Nodes repeatedly exchange partial membership or state until information converges probabilistically.","tradeoff":"Scales well but propagation is delayed and approximate.","visualPath":"../assets/data/system-design-visuals/2a55282fca689958.json"},{"name":"Failure detectors","summary":"Heartbeats and timeouts produce suspicions because delay is indistinguishable from failure in an asynchronous network.","tradeoff":"Fast detection increases false positives.","visualPath":"../assets/data/system-design-visuals/54b020b1cecd7fb6.json"},{"name":"FLP impossibility","summary":"Deterministic consensus cannot guarantee termination in a fully asynchronous system with even one crash failure.","tradeoff":"Practical liveness relies on timing assumptions or randomness.","visualPath":"../assets/data/system-design-visuals/a038fb198bd6efd1.json"},{"name":"Split brain","summary":"Multiple nodes simultaneously believe they are authoritative and may accept conflicting work.","tradeoff":"Preventing it intentionally stops minority-side progress.","visualPath":"../assets/data/system-design-visuals/c0ecfd319e6f28e5.json"},{"name":"Byzantine vs crash failures","summary":"Crash failures stop a participant; Byzantine failures allow arbitrary or contradictory behavior and need stronger protocols.","tradeoff":"Byzantine tolerance requires more replicas and messages.","visualPath":"../assets/data/system-design-visuals/b86d179a48440ac4.json"},{"name":"Time and clocks","summary":"Distributed time is uncertain, so systems separate human time, duration measurement, causality, and ordering.","tradeoff":"No single clock mechanism serves every purpose.","visualPath":"../assets/data/system-design-visuals/7ffbfb5e14811ead.json"},{"name":"Physical clocks","summary":"Physical clocks approximate wall time and are synchronized within an error bound.","tradeoff":"Skew and clock adjustments make them unsafe as sole ordering evidence.","visualPath":"../assets/data/system-design-visuals/37a8dd76ee365912.json"},{"name":"Logical clocks","summary":"Logical clocks derive ordering from events and messages rather than wall time.","tradeoff":"They express order but not real elapsed time.","visualPath":"../assets/data/system-design-visuals/a529f6ee0e77dbba.json"},{"name":"Lamport clocks","summary":"Counters ensure that causal precedence implies increasing timestamps, with tie-breakers providing a total order.","tradeoff":"They cannot distinguish concurrency.","visualPath":"../assets/data/system-design-visuals/447fd29486bfab61.json"},{"name":"Vector clocks","summary":"Per-participant counters identify whether versions are ordered or concurrent.","tradeoff":"Metadata grows with the writer set.","visualPath":"../assets/data/system-design-visuals/62ef90cda2cf2368.json"},{"name":"Hybrid logical clocks","summary":"Hybrid logical clocks combine bounded physical time with logical counters while preserving causality.","tradeoff":"Time-based claims still depend on a clock-skew bound.","visualPath":"../assets/data/system-design-visuals/1bc0c72c1909a9b9.json"},{"name":"Idempotency","summary":"Repeating an operation with the same identity produces the same durable effect.","tradeoff":"Requires stable keys and retained outcome state.","visualPath":"../assets/data/system-design-visuals/d9d2d5d4b6c13498.json"},{"name":"Delivery semantics","summary":"Delivery semantics define whether messages may be lost or repeated and where the guarantee ends.","tradeoff":"Stronger semantics require durable state and coordination.","visualPath":"../assets/data/system-design-visuals/2ac8e3585ca44526.json"},{"name":"At-most-once","summary":"A message is attempted no more than once, avoiding duplicates but allowing loss.","tradeoff":"Suitable only when loss is acceptable.","visualPath":"../assets/data/system-design-visuals/bf36469f996000cd.json"},{"name":"At-least-once","summary":"A message is retried until acknowledged, preventing intentional loss but allowing duplicates.","tradeoff":"Consumers must be idempotent.","visualPath":"../assets/data/system-design-visuals/db4d83073e1e6d11.json"},{"name":"Exactly-once","summary":"One logical effect occurs once within a precisely defined transactional or deduplicated boundary.","tradeoff":"External side effects remain difficult and coordination is expensive.","visualPath":"../assets/data/system-design-visuals/ba8d78ddfe797ce5.json"},{"name":"Ordering","summary":"Ordering defines which observers must agree on the relative position of operations or messages.","tradeoff":"Broader ordering reduces parallelism.","visualPath":"../assets/data/system-design-visuals/7600f8c185434df7.json"},{"name":"FIFO ordering","summary":"Messages from one producer or partition are observed in send order.","tradeoff":"Does not order independent producers.","visualPath":"../assets/data/system-design-visuals/39c31cb571eb4910.json"},{"name":"Causal ordering","summary":"Messages related by happened-before are delivered in causal order while concurrent messages may vary.","tradeoff":"Requires dependency metadata.","visualPath":"../assets/data/system-design-visuals/378b9c17509e0632.json"},{"name":"Total ordering","summary":"All participants observe all ordered items in the same sequence.","tradeoff":"Global agreement limits throughput and availability.","visualPath":"../assets/data/system-design-visuals/fea893b833185164.json"}]}]},{"id":"consensus-coordination","title":"Consensus & Coordination","intro":"Coordinate only the decisions that require one durable order or exclusive owner.","groups":[{"title":"Consensus and leadership","concepts":[{"name":"Paxos","summary":"Numbered proposals and intersecting acceptor quorums ensure only one value is chosen for a slot.","tradeoff":"Correct but subtle to implement and operate.","visualPath":"../assets/data/system-design-visuals/26c4500abdfec1b5.json"},{"name":"Raft","summary":"An elected leader replicates an ordered log and commits entries after majority acknowledgement.","tradeoff":"Leader dependence and quorum loss pause progress.","visualPath":"../assets/data/system-design-visuals/4465ade42f134051.json"},{"name":"Leader election","summary":"Participants choose one leader for a term after verifying candidate freshness and quorum support.","tradeoff":"Elections pause work and can thrash under instability.","visualPath":"../assets/data/system-design-visuals/165770e75afecb0e.json"},{"name":"Quorum consensus","summary":"Intersecting quorums preserve chosen decisions across failures and leadership changes.","tradeoff":"Cannot progress safely without enough reachable voters.","visualPath":"../assets/data/system-design-visuals/7da9516d8548e16b.json"},{"name":"Distributed locks","summary":"A linearizable coordinator grants exclusive ownership of a named resource for bounded or explicit tenure.","tradeoff":"Serializes work and can become a bottleneck.","visualPath":"../assets/data/system-design-visuals/df06787c68e92c21.json"},{"name":"Leases","summary":"A lease grants time-bounded ownership that must be renewed and fenced after expiry.","tradeoff":"Short leases improve failover but amplify renewal load and pause sensitivity.","visualPath":"../assets/data/system-design-visuals/a4462c3614147003.json"},{"name":"Fencing tokens","summary":"Each ownership grant carries a monotonically increasing token that protected resources use to reject stale holders.","tradeoff":"Every side-effecting resource must enforce the token.","visualPath":"../assets/data/system-design-visuals/ebd4b60a1582b8d0.json"},{"name":"Compare-and-swap","summary":"Compare-and-swap updates a value only if its current version matches an expected version.","tradeoff":"Contention causes retries and possible starvation.","visualPath":"../assets/data/system-design-visuals/c9a055fa3b27414f.json"}]},{"title":"Coordination services and membership","concepts":[{"name":"Distributed coordination","summary":"Distributed coordination manages shared metadata, membership, ownership, or ordered configuration through a consistent control plane.","tradeoff":"Adds a critical dependency and coordination latency.","visualPath":"../assets/data/system-design-visuals/6cb4fb87ef3f2a90.json"},{"name":"Zookeeper-style coordination","summary":"A hierarchical, strongly ordered namespace supports ephemeral membership, watches, locks, and leader election.","tradeoff":"Watch and session semantics require careful client handling.","visualPath":"../assets/data/system-design-visuals/325017a8dda33589.json"},{"name":"etcd-style coordination","summary":"A replicated key-value store exposes linearizable operations, revisions, watches, and leases for control-plane state.","tradeoff":"Keep values and write volume small to protect consensus throughput.","visualPath":"../assets/data/system-design-visuals/bba3fcf7043b2b87.json"},{"name":"Membership protocols","summary":"Membership tracks participating nodes and generations through consensus or gossip.","tradeoff":"Fast membership changes can destabilize placement and failover.","visualPath":"../assets/data/system-design-visuals/c59c43ed960ad61f.json"},{"name":"Leader/follower","summary":"One leader orders control operations while followers replicate state and stand ready for election.","tradeoff":"Simple authority model with leader bottlenecks.","visualPath":"../assets/data/system-design-visuals/21112098481dcc2c.json"},{"name":"Primary/backup","summary":"A primary performs work while backups receive enough state to take over after fencing.","tradeoff":"Standby capacity and promotion correctness cost resources.","visualPath":"../assets/data/system-design-visuals/bf28bb9f02df16e9.json"},{"name":"Term/epoch management","summary":"Monotonic generations distinguish current authority from delayed messages and stale leaders.","tradeoff":"Epoch state must be durably persisted and propagated.","visualPath":"../assets/data/system-design-visuals/d2203b0b2de79d95.json"},{"name":"Split-brain prevention","summary":"Quorums, epochs, and fencing ensure at most one side can commit authoritative work.","tradeoff":"Minority partitions become unavailable.","visualPath":"../assets/data/system-design-visuals/5a87d0dd32ebb2a5.json"}]}]},{"id":"replication","title":"Replication","intro":"Select replica topology by write authority, acknowledgement point, lag, and conflict semantics.","groups":[{"title":"Replication topologies","concepts":[{"name":"Leader/follower replication","summary":"A leader orders writes and followers replay its log, optionally serving lag-tolerant reads.","tradeoff":"The leader is a bottleneck and failover pauses writes.","visualPath":"../assets/data/system-design-visuals/41f3014e1fd31343.json"},{"name":"Multi-leader replication","summary":"Multiple leaders accept local writes and exchange updates asynchronously.","tradeoff":"Concurrent updates require conflict resolution.","visualPath":"../assets/data/system-design-visuals/22e6462a24cb1888.json"},{"name":"Leaderless replication","summary":"Clients read and write multiple replicas without a permanent write leader.","tradeoff":"Version reconciliation and tail latency move to the request path.","visualPath":"../assets/data/system-design-visuals/6c73c35ef2f22b13.json"},{"name":"Synchronous replication","summary":"Success waits until required replicas durably accept the write.","tradeoff":"Remote latency and failures affect write availability.","visualPath":"../assets/data/system-design-visuals/7b72471e6fdbf504.json"},{"name":"Asynchronous replication","summary":"The authority acknowledges before remote replicas persist the update.","tradeoff":"Failover may lose acknowledged writes and serve stale data.","visualPath":"../assets/data/system-design-visuals/8405ceb9c9a83871.json"},{"name":"Semi-synchronous replication","summary":"Success waits for limited replica acknowledgement while remaining copies catch up asynchronously.","tradeoff":"The exact acknowledgement stage may not imply remote durability.","visualPath":"../assets/data/system-design-visuals/e2f4d951ee7f8897.json"},{"name":"Quorum replication","summary":"Reads and writes contact configurable replica subsets whose overlap carries recent state.","tradeoff":"Quorum size trades latency against consistency and availability.","visualPath":"../assets/data/system-design-visuals/3075b7db8c97faba.json"},{"name":"Chain replication","summary":"Writes flow through an ordered replica chain and reads commonly use the tail, separating update propagation from read authority.","tradeoff":"Chain repair and tail latency matter during failures.","visualPath":"../assets/data/system-design-visuals/1e7f81e07afd313b.json"},{"name":"Read replicas","summary":"Replicas serve read traffic to improve scale and locality under an explicit staleness policy.","tradeoff":"Replica lag causes stale and non-monotonic reads.","visualPath":"../assets/data/system-design-visuals/e2616d0133c75291.json"},{"name":"Write replicas","summary":"Write replicas durably accept updates as leaders, quorum members, or multi-writer peers.","tradeoff":"More write authorities increase coordination or conflict cost.","visualPath":"../assets/data/system-design-visuals/64374cffdfa7f8ba.json"}]},{"title":"Lag, conflicts, and geography","concepts":[{"name":"Replication lag","summary":"Lag measures how far a replica trails authoritative state in time, bytes, or versions.","tradeoff":"Lower lag consumes more bandwidth and apply capacity.","visualPath":"../assets/data/system-design-visuals/950375d0d5477e9d.json"},{"name":"Conflict resolution","summary":"Concurrent replica updates are detected and merged by deterministic technical or domain rules.","tradeoff":"Automatic convergence may discard user intent.","visualPath":"../assets/data/system-design-visuals/af81386f41d8b78a.json"},{"name":"Last-write-wins","summary":"The update with the greatest timestamp or version wins and all replicas converge on it.","tradeoff":"Simple but can silently lose concurrent writes.","visualPath":"../assets/data/system-design-visuals/e887fc07b07e5a42.json"},{"name":"Version vectors","summary":"Per-writer version components distinguish causal descendants from concurrent siblings.","tradeoff":"Metadata grows and needs compaction.","visualPath":"../assets/data/system-design-visuals/5eb32e6dbf52ccc0.json"},{"name":"CRDTs","summary":"Conflict-free replicated data types merge state or operations so replicas converge independent of delivery order.","tradeoff":"Only fits data with suitable merge semantics.","visualPath":"../assets/data/system-design-visuals/c72bd35dcd0fc598.json"},{"name":"Active-active replication","summary":"Multiple sites serve traffic simultaneously and partition, coordinate, or reconcile writes.","tradeoff":"Best locality and utilization with hardest consistency model.","visualPath":"../assets/data/system-design-visuals/a3add4c4a38f029c.json"},{"name":"Active-passive replication","summary":"One site serves traffic while a synchronized standby is promoted after failure.","tradeoff":"Simpler conflicts but idle capacity and failover delay.","visualPath":"../assets/data/system-design-visuals/16fbfaa01c91a649.json"},{"name":"Cross-region replication","summary":"Copies span cloud regions to improve locality and regional disaster recovery.","tradeoff":"Distance increases latency, cost, and failover complexity.","visualPath":"../assets/data/system-design-visuals/67f37c364ae821d9.json"},{"name":"Cross-datacenter replication","summary":"Copies cross independent datacenters to survive facility-level faults.","tradeoff":"Network variability and correlated control planes must be considered.","visualPath":"../assets/data/system-design-visuals/075be36b81be11be.json"}]}]},{"id":"partitioning-sharding","title":"Partitioning / Sharding","intro":"Partition for locality and balance while planning for skew, movement, and fan-out.","groups":[{"title":"Placement strategies","concepts":[{"name":"Hash partitioning","summary":"A key hash maps data to buckets and usually distributes high-cardinality keys evenly.","tradeoff":"Loses range locality and complicates membership changes.","visualPath":"../assets/data/system-design-visuals/88c5451862cc0075.json"},{"name":"Consistent hashing","summary":"Keys and nodes share a ring so membership changes move only nearby ranges.","tradeoff":"Balance is approximate and ownership metadata grows.","visualPath":"../assets/data/system-design-visuals/11383a06333eab52.json"},{"name":"Rendezvous hashing","summary":"Each key scores candidate nodes and selects the highest-ranked owners with minimal movement.","tradeoff":"Naive routing evaluates every candidate.","visualPath":"../assets/data/system-design-visuals/ed8eb5d9d6e41602.json"},{"name":"Range partitioning","summary":"Contiguous key intervals map to shards, enabling efficient ordered scans.","tradeoff":"Monotonic or skewed keys create hotspots.","visualPath":"../assets/data/system-design-visuals/208095a89a7deec2.json"},{"name":"Directory-based partitioning","summary":"A versioned directory explicitly maps keys or ranges to shard owners.","tradeoff":"Flexible placement adds a metadata dependency.","visualPath":"../assets/data/system-design-visuals/080200aa6a6bb10d.json"},{"name":"Virtual nodes","summary":"Many logical tokens per physical node smooth distribution and capacity weighting.","tradeoff":"More fragmented ownership and transfer metadata.","visualPath":"../assets/data/system-design-visuals/b553088bb705c5d5.json"}]},{"title":"Movement and skew","concepts":[{"name":"Rebalancing","summary":"Ownership moves between nodes using copy, catch-up, versioned cutover, and source retirement.","tradeoff":"Movement competes with foreground traffic.","visualPath":"../assets/data/system-design-visuals/38bb19e87dccc380.json"},{"name":"Hot partitions","summary":"A partition saturates because its traffic or data grows faster than peers.","tradeoff":"Splitting or isolating it can reduce locality.","visualPath":"../assets/data/system-design-visuals/99bd1faeff51cdb5.json"},{"name":"Hot keys","summary":"One logical key dominates a partition despite otherwise balanced placement.","tradeoff":"Salting or replication complicates ordering and reads.","visualPath":"../assets/data/system-design-visuals/ab3fc52511df8802.json"},{"name":"Shard splitting","summary":"An oversized or hot shard divides into independently owned children.","tradeoff":"Splits add routing changes and migration I/O.","visualPath":"../assets/data/system-design-visuals/ab5dd80e7b8c9b78.json"},{"name":"Shard merging","summary":"Small adjacent shards combine to reduce overhead and fragmentation.","tradeoff":"Merge work consumes I/O and can recreate hotspots.","visualPath":"../assets/data/system-design-visuals/f1bda47a89de2166.json"},{"name":"Dynamic partitioning","summary":"The system adjusts partition boundaries or ownership from observed size and load.","tradeoff":"Automation can oscillate without hysteresis and movement budgets.","visualPath":"../assets/data/system-design-visuals/bad2a70d194da323.json"}]},{"title":"Query and tenancy behavior","concepts":[{"name":"Scatter-gather","summary":"A query fans out to relevant shards and merges their responses.","tradeoff":"Latency follows stragglers and cost grows with shard count.","visualPath":"../assets/data/system-design-visuals/871328cad6f13baf.json"},{"name":"Fan-out","summary":"One request expands into many downstream operations or messages.","tradeoff":"Amplifies load and tail-failure probability.","visualPath":"../assets/data/system-design-visuals/7fec67336e702827.json"},{"name":"Partition affinity","summary":"Related work is routed to the same partition to preserve locality, order, or cache reuse.","tradeoff":"Affinity can cause skew and constrain failover.","visualPath":"../assets/data/system-design-visuals/1607ad2bd1081740.json"},{"name":"Tenant-based partitioning","summary":"Tenant identity drives placement to improve isolation, locality, or compliance.","tradeoff":"Large tenants require subpartitioning and migration support.","visualPath":"../assets/data/system-design-visuals/a728febead1d9f2f.json"}]}]},{"id":"distributed-caching","title":"Distributed Caching","intro":"Design cached data as a disposable copy with explicit freshness and refill behavior.","groups":[{"title":"Access patterns","concepts":[{"name":"Cache-aside","summary":"The application loads misses from the source and explicitly fills or invalidates the cache.","tradeoff":"Simple but exposes refill and invalidation races.","visualPath":"../assets/data/system-design-visuals/3255146b6fbb8d4a.json"},{"name":"Read-through cache","summary":"The cache invokes a loader on misses and presents one read interface.","tradeoff":"Couples cache infrastructure to the source and serialization.","visualPath":"../assets/data/system-design-visuals/f921368b16026cf1.json"},{"name":"Write-through cache","summary":"Writes synchronously update both cache and source before success.","tradeoff":"Every write pays both paths.","visualPath":"../assets/data/system-design-visuals/08a536169ebd5b00.json"},{"name":"Write-behind cache","summary":"Writes land in cache and are asynchronously persisted, often with batching.","tradeoff":"Cache failure can lose acknowledged data.","visualPath":"../assets/data/system-design-visuals/1a98def65178b939.json"},{"name":"Refresh-ahead","summary":"Popular entries are refreshed before expiry to avoid user-visible misses.","tradeoff":"May refresh data that is never reused.","visualPath":"../assets/data/system-design-visuals/36e2ab6f8a30871b.json"},{"name":"Cache warming","summary":"Likely hot entries are preloaded before traffic or after fleet changes.","tradeoff":"Consumes source capacity and can predict poorly.","visualPath":"../assets/data/system-design-visuals/c5930200a0b2cefd.json"}]},{"title":"Freshness and misses","concepts":[{"name":"Cache invalidation","summary":"Changed source data removes, updates, or versions cached copies through an ordered policy.","tradeoff":"Precise invalidation increases write-path coupling.","visualPath":"../assets/data/system-design-visuals/725099f25f08180d.json"},{"name":"TTL","summary":"A time to live bounds entry freshness and should include jitter to avoid synchronized expiry.","tradeoff":"Short TTLs increase misses and source load.","visualPath":"../assets/data/system-design-visuals/1431314cd59740fe.json"},{"name":"Negative caching","summary":"Not-found or failed lookups are cached briefly to prevent repeated expensive misses.","tradeoff":"Can hide newly created data or prolong transient errors.","visualPath":"../assets/data/system-design-visuals/31055c7d68a7312f.json"},{"name":"Cache stampede","summary":"Many requests simultaneously reload the same expired or evicted value.","tradeoff":"Prevention adds coordination or permits stale reads.","visualPath":"../assets/data/system-design-visuals/cfc90099f14fdaa6.json"},{"name":"Thundering herd","summary":"A large client population wakes or retries together and overwhelms a dependency.","tradeoff":"Jitter and admission control delay some clients.","visualPath":"../assets/data/system-design-visuals/3c4625661c1d2f37.json"},{"name":"Request coalescing","summary":"Concurrent requests for the same resource share one in-flight load.","tradeoff":"One slow load delays every waiter.","visualPath":"../assets/data/system-design-visuals/3730168c612375b2.json"},{"name":"Single-flight","summary":"Exactly one loader per key performs a miss refill while peers await its result.","tradeoff":"Requires cleanup and bounded waiting when the loader fails.","visualPath":"../assets/data/system-design-visuals/2ad37c4044f87e64.json"},{"name":"Probabilistic early expiration","summary":"Requests randomly refresh near expiry so popular keys renew before a synchronized miss.","tradeoff":"Some entries refresh earlier than necessary.","visualPath":"../assets/data/system-design-visuals/0fc8e900c1c37f21.json"}]},{"title":"Topology and correctness","concepts":[{"name":"Distributed cache","summary":"Cached entries are partitioned and optionally replicated across multiple cache nodes.","tradeoff":"Node loss remaps keys and can trigger miss storms.","visualPath":"../assets/data/system-design-visuals/23deca9b5a5132f9.json"},{"name":"Local + distributed cache","summary":"A process-local near-cache fronts a shared distributed cache to remove network latency for hot values.","tradeoff":"Two cache layers multiply invalidation and staleness paths.","visualPath":"../assets/data/system-design-visuals/03a6888762df73a2.json"},{"name":"Cache consistency","summary":"The cache contract defines how cached versions relate to authoritative source updates.","tradeoff":"Stronger consistency reduces latency and availability benefits.","visualPath":"../assets/data/system-design-visuals/d78fa66eb7ec77e3.json"},{"name":"Cache versioning","summary":"Keys or values carry generations so stale fills cannot replace newer data.","tradeoff":"Requires version propagation and temporary duplication.","visualPath":"../assets/data/system-design-visuals/6e249a7fa82a641f.json"},{"name":"Hot-key mitigation","summary":"Replicate, near-cache, coalesce, or split work for keys that saturate one cache owner.","tradeoff":"More copies and routing rules complicate invalidation.","visualPath":"../assets/data/system-design-visuals/528bfa06986b7c9e.json"}]}]},{"id":"probabilistic-data-structures","title":"Probabilistic / Approximate Data Structures","intro":"Use explicit error guarantees to exchange exactness for bounded memory and computation.","groups":[{"title":"Membership","concepts":[{"name":"Bloom filter","summary":"Multiple hashes set bits to test membership with no false negatives and configurable false positives.","tradeoff":"Standard filters cannot safely delete.","visualPath":"../assets/data/system-design-visuals/cdb3c7a6a6320446.json"},{"name":"Counting Bloom filter","summary":"Counters replace bits so insertions can be removed while preserving membership tests.","tradeoff":"Deletion support costs substantially more memory.","visualPath":"../assets/data/system-design-visuals/976b7d23fb99082e.json"},{"name":"Cuckoo filter","summary":"Short fingerprints occupy alternative buckets and relocate on collision, supporting lookup and deletion.","tradeoff":"Insertion can fail near high occupancy.","visualPath":"../assets/data/system-design-visuals/f7eda480742a3f5f.json"},{"name":"Quotient filter","summary":"Compact hash quotients and remainders support membership, deletion, and locality-friendly scans.","tradeoff":"Performance degrades at high load factors.","visualPath":"../assets/data/system-design-visuals/c3d0d4b09f88d838.json"}]},{"title":"Cardinality and frequency","concepts":[{"name":"HyperLogLog","summary":"Register maxima from hashed leading-zero counts estimate distinct cardinality in fixed memory.","tradeoff":"Returns a statistical estimate, not members.","visualPath":"../assets/data/system-design-visuals/e812e4ac360cc1b1.json"},{"name":"Count-Min Sketch","summary":"Hashed counter rows estimate frequency by taking the minimum counter for an item.","tradeoff":"Collisions cause overestimation.","visualPath":"../assets/data/system-design-visuals/bfd251b8a47db4bd.json"},{"name":"Heavy hitters","summary":"Bounded algorithms identify items above a meaningful stream-frequency threshold.","tradeoff":"Candidates near the threshold may be approximate.","visualPath":"../assets/data/system-design-visuals/6ef26257e4e3f9c5.json"},{"name":"Top-K sketches","summary":"Frequency sketches plus bounded candidate tracking estimate the most frequent items.","tradeoff":"Close-ranked items may be omitted or reordered.","visualPath":"../assets/data/system-design-visuals/226a97d89c1178b4.json"},{"name":"HyperLogLog++","summary":"HyperLogLog++ improves small-cardinality bias, sparse representation, and estimator accuracy.","tradeoff":"More implementation complexity than basic HyperLogLog.","visualPath":"../assets/data/system-design-visuals/92df8d462077f275.json"},{"name":"Approximate distinct counting","summary":"A compact sketch estimates unique items and can often merge summaries from many partitions.","tradeoff":"Accuracy depends on memory and estimator assumptions.","visualPath":"../assets/data/system-design-visuals/4f62ebd33da66ca1.json"},{"name":"Probabilistic counters","summary":"Counters update with decreasing probability as values grow, representing large counts in few bits.","tradeoff":"Relative error replaces exact increments.","visualPath":"../assets/data/system-design-visuals/18e3fad633f5e38e.json"}]},{"title":"Similarity and sampling","concepts":[{"name":"MinHash","summary":"Minimum hash signatures estimate Jaccard similarity between sets.","tradeoff":"More signature components improve accuracy at memory cost.","visualPath":"../assets/data/system-design-visuals/55032455672c390a.json"},{"name":"SimHash","summary":"A weighted bit signature preserves angular similarity and supports near-duplicate detection by Hamming distance.","tradeoff":"Best for cosine-like similarity, not arbitrary distance metrics.","visualPath":"../assets/data/system-design-visuals/a45a9c48fa40c323.json"},{"name":"Locality-sensitive hashing","summary":"A metric-specific hash family places similar items together with higher probability.","tradeoff":"Approximate search can miss true neighbors.","visualPath":"../assets/data/system-design-visuals/792a4dbd02d53e68.json"},{"name":"Reservoir sampling","summary":"A fixed-size uniform sample is maintained from a stream of unknown length.","tradeoff":"Rare subgroups may be absent.","visualPath":"../assets/data/system-design-visuals/01d3e8cfe2804f63.json"},{"name":"Sampling algorithms","summary":"Uniform, weighted, stratified, or adaptive sampling reduces data while preserving defined statistical properties.","tradeoff":"Incorrect sampling frames create biased conclusions.","visualPath":"../assets/data/system-design-visuals/717b434131968f98.json"}]}]},{"id":"distributed-messaging-eventing","title":"Distributed Messaging & Eventing","intro":"Separate durable history, delivery attempts, consumer progress, and committed side effects.","groups":[{"title":"Messaging models","concepts":[{"name":"Message queues","summary":"Queues buffer work and distribute each message to one competing consumer.","tradeoff":"Decoupling introduces retries, duplicates, and queue delay.","visualPath":"../assets/data/system-design-visuals/39da7db5be21b126.json"},{"name":"Pub/Sub","summary":"Publishers emit once while independent subscriptions each receive and track the event.","tradeoff":"Fan-out multiplies delivery and compatibility costs.","visualPath":"../assets/data/system-design-visuals/38f8d2d2ee347f1c.json"},{"name":"Event streaming","summary":"Durable ordered event sequences support continuous processing and replay.","tradeoff":"Retention and stateful consumers increase operational complexity.","visualPath":"../assets/data/system-design-visuals/f97d0846e10cae86.json"},{"name":"Kafka-style logs","summary":"Replicated partition logs append records at offsets and let consumers manage replayable progress.","tradeoff":"Ordering is normally partition-scoped.","visualPath":"../assets/data/system-design-visuals/79a6cfa08df63178.json"},{"name":"Consumer groups","summary":"Group members divide partitions so one active member processes each partition for that group.","tradeoff":"Parallelism is bounded by partition count and rebalances pause work.","visualPath":"../assets/data/system-design-visuals/d48da2bb126ef8ac.json"},{"name":"Partitioning","summary":"A routing key maps messages to ordered, independently scalable log or queue partitions.","tradeoff":"Bad keys create hotspots or break required ordering.","visualPath":"../assets/data/system-design-visuals/cdc1907816395e9c.json"}]},{"title":"Progress and retention","concepts":[{"name":"Offsets","summary":"An offset identifies a stable position within an ordered partition.","tradeoff":"It names broker position, not committed business effects.","visualPath":"../assets/data/system-design-visuals/b467a0d36037d58f.json"},{"name":"Consumer offsets","summary":"A consumer offset records group progress and must be coordinated with side effects.","tradeoff":"Early commits lose work; late commits duplicate it.","visualPath":"../assets/data/system-design-visuals/f18e2b0289d71d6b.json"},{"name":"Replay","summary":"Consumers reset progress and reprocess retained history to recover or rebuild state.","tradeoff":"Side effects and old schemas must remain replay-safe.","visualPath":"../assets/data/system-design-visuals/08c86da57d02f25e.json"},{"name":"Retention","summary":"Time- or size-based policy determines how long messages remain replayable.","tradeoff":"Long retention costs storage and extends compatibility obligations.","visualPath":"../assets/data/system-design-visuals/18d65acaa66a00e2.json"},{"name":"Compaction","summary":"Log compaction retains the latest value or tombstone per key while preserving an update stream.","tradeoff":"Removes intermediate history and needs safe tombstone retention.","visualPath":"../assets/data/system-design-visuals/27588afe60781d9a.json"}]},{"title":"Delivery control","concepts":[{"name":"Dead-letter queues","summary":"Messages exceeding retry or validation policy are isolated for diagnosis and controlled replay.","tradeoff":"Without ownership and alerts, a DLQ becomes silent data loss.","visualPath":"../assets/data/system-design-visuals/f168a0556eafb3b4.json"},{"name":"Retry queues","summary":"Transient failures are rescheduled with attempt metadata and backoff outside the main flow.","tradeoff":"Retries reorder messages and extend latency.","visualPath":"../assets/data/system-design-visuals/2e3331019cc9058b.json"},{"name":"Delayed queues","summary":"Messages become eligible only after a scheduled time, supporting retry and workflow timers.","tradeoff":"Scheduling precision and cancellation add state.","visualPath":"../assets/data/system-design-visuals/607f4ab4c8c99b12.json"},{"name":"Priority queues","summary":"Higher-priority messages are selected before lower-priority work within fairness constraints.","tradeoff":"Low-priority traffic can starve.","visualPath":"../assets/data/system-design-visuals/84c0c9487f5d8ad0.json"},{"name":"Message ordering","summary":"A broker and consumer preserve a declared order scope, usually one partition key.","tradeoff":"Ordering constrains parallel consumption.","visualPath":"../assets/data/system-design-visuals/5a5e6ea9e7708f3b.json"},{"name":"Exactly-once processing","summary":"Input progress and output state commit atomically inside a supported processing boundary.","tradeoff":"External effects still require idempotency or transactions.","visualPath":"../assets/data/system-design-visuals/cf57a19a9d43d8dc.json"},{"name":"Idempotent consumers","summary":"Repeated delivery produces one durable business outcome using natural semantics or deduplication state.","tradeoff":"Requires stable message identities and retention.","visualPath":"../assets/data/system-design-visuals/de2db8b4cf4a6f0a.json"},{"name":"Transactional messaging","summary":"Message production or consumption participates in an atomic transaction with supported state changes.","tradeoff":"Broker coupling and coordination reduce throughput.","visualPath":"../assets/data/system-design-visuals/f89a166b81d48f87.json"}]},{"title":"Integration patterns","concepts":[{"name":"Outbox pattern","summary":"Business state and an outgoing message record commit together, then a relay publishes the record.","tradeoff":"Publication is delayed and may duplicate.","visualPath":"../assets/data/system-design-visuals/90e2fd5a70abf5c4.json"},{"name":"Inbox pattern","summary":"A consumed message identity and local effect commit together to suppress duplicate effects.","tradeoff":"Inbox state needs cleanup and retention rules.","visualPath":"../assets/data/system-design-visuals/0eb8131e55d84887.json"},{"name":"Change Data Capture","summary":"Committed database log changes are emitted for replication, events, or projections.","tradeoff":"Schema changes and downstream lag require careful operations.","visualPath":"../assets/data/system-design-visuals/56f2ce294111b265.json"},{"name":"Event sourcing","summary":"Immutable domain events are authoritative and current state is reconstructed by replay or snapshots.","tradeoff":"Event evolution and projection repair are complex.","visualPath":"../assets/data/system-design-visuals/457f4ab753335e6f.json"}]}]},{"id":"distributed-transactions","title":"Distributed Transactions","intro":"Keep invariants local when possible and make every multi-step outcome durable and recoverable.","groups":[{"title":"Atomic commit","concepts":[{"name":"Two-phase commit (2PC)","summary":"Participants durably prepare before a coordinator records and broadcasts commit or abort.","tradeoff":"Prepared resources can block during coordinator failure.","visualPath":"../assets/data/system-design-visuals/83515f3b958c5ed3.json"},{"name":"Three-phase commit","summary":"An added pre-commit phase reduces blocking only under restrictive timing and partition assumptions.","tradeoff":"More messages without practical partition safety in common systems.","visualPath":"../assets/data/system-design-visuals/532cdc3db5895a45.json"},{"name":"XA transactions","summary":"XA standardizes transaction-manager coordination of resource managers using prepare and commit phases.","tradeoff":"Tight coupling, blocking, and difficult cross-resource operations.","visualPath":"../assets/data/system-design-visuals/f64a8d11841e42b8.json"},{"name":"Atomic commit","summary":"All participating resources reach one durable commit or abort decision.","tradeoff":"Agreement adds latency and can block progress.","visualPath":"../assets/data/system-design-visuals/a38708d51c469191.json"}]},{"title":"Long-running workflows","concepts":[{"name":"Saga pattern","summary":"A durable sequence of local transactions uses compensations when a later step fails.","tradeoff":"Intermediate states are visible and rollback is semantic.","visualPath":"../assets/data/system-design-visuals/9d11f73b427d05c1.json"},{"name":"Choreography","summary":"Services advance a workflow by reacting to one another through events.","tradeoff":"Loose coupling obscures the global state machine.","visualPath":"../assets/data/system-design-visuals/5f88fb99a0fe2b1f.json"},{"name":"Orchestration","summary":"A durable coordinator commands steps and tracks replies, retries, timeouts, and compensation.","tradeoff":"Clear control creates coordinator coupling.","visualPath":"../assets/data/system-design-visuals/0a972aa701a39aaf.json"},{"name":"Compensating transactions","summary":"Business actions counteract previously committed steps and must be idempotent and recoverable.","tradeoff":"Compensation may not restore the exact prior state.","visualPath":"../assets/data/system-design-visuals/d5fad443cc649110.json"},{"name":"Transactional outbox","summary":"A local transaction atomically stores business changes and a pending integration event.","tradeoff":"Needs an asynchronous relay, deduplication, and cleanup.","visualPath":"../assets/data/system-design-visuals/aafa2531e65f284d.json"}]},{"title":"Concurrency control","concepts":[{"name":"Distributed locking","summary":"Exclusive ownership spans processes through a consistent lock service and fencing.","tradeoff":"Locks reduce availability and can hold remote resources.","visualPath":"../assets/data/system-design-visuals/f8332a3ccc867ce1.json"},{"name":"Optimistic concurrency","summary":"Operations proceed without long locks and validate expected versions before commit.","tradeoff":"High contention causes retries and wasted work.","visualPath":"../assets/data/system-design-visuals/e8b3fe1e5e6fd637.json"},{"name":"Pessimistic concurrency","summary":"Locks prevent conflicting work before it executes.","tradeoff":"Waiting and deadlocks reduce concurrency.","visualPath":"../assets/data/system-design-visuals/cb130fd0839adf8b.json"},{"name":"MVCC","summary":"Multiple versions let readers use stable snapshots while writers create new committed versions.","tradeoff":"Long snapshots increase storage and cleanup pressure.","visualPath":"../assets/data/system-design-visuals/8ca609ef2d98d85f.json"},{"name":"Snapshot isolation","summary":"Transactions read a consistent snapshot and typically reject concurrent writes to the same item.","tradeoff":"Write skew can violate cross-item invariants.","visualPath":"../assets/data/system-design-visuals/d1fa533a946f0957.json"},{"name":"Serializable transactions","summary":"Concurrent transactions produce an outcome equivalent to some serial execution.","tradeoff":"Contention causes blocking or aborts.","visualPath":"../assets/data/system-design-visuals/ddedb623ca18074c.json"},{"name":"Idempotent operations","summary":"A stable operation identity makes retries converge on one recorded transaction outcome.","tradeoff":"Deduplication state needs scope and expiry.","visualPath":"../assets/data/system-design-visuals/36a99e725f608fac.json"}]}]},{"id":"reliability-fault-tolerance","title":"Reliability & Fault Tolerance","intro":"Bound resource use, isolate dependency failures, and recover within explicit objectives.","groups":[{"title":"Remote-call resilience","concepts":[{"name":"Timeouts","summary":"Timeouts bound individual waits using the remaining end-to-end deadline and expected latency.","tradeoff":"Too short creates false failures; too long retains resources.","visualPath":"../assets/data/system-design-visuals/af81275eb6f97177.json"},{"name":"Retries","summary":"Retries repeat classified transient failures only when operations are safe and budget remains.","tradeoff":"They amplify load and can duplicate side effects.","visualPath":"../assets/data/system-design-visuals/64c1ba207c91187a.json"},{"name":"Exponential backoff","summary":"Delay grows between attempts so a recovering dependency is not continuously hammered.","tradeoff":"Recovery takes longer for individual requests.","visualPath":"../assets/data/system-design-visuals/ccf8134662eb85ef.json"},{"name":"Jitter","summary":"Randomized timing prevents synchronized retries, refreshes, and reconnects.","tradeoff":"Adds variability to client latency.","visualPath":"../assets/data/system-design-visuals/1b74d17e4d1b7b19.json"},{"name":"Retry budgets","summary":"A bounded fraction of capacity or traffic may be spent on retries.","tradeoff":"Some recoverable work is abandoned to protect the system.","visualPath":"../assets/data/system-design-visuals/01d863775bcd02be.json"},{"name":"Circuit breakers","summary":"Repeated classified failures open a circuit that fails fast before probing recovery.","tradeoff":"Bad thresholds reject healthy traffic or flap.","visualPath":"../assets/data/system-design-visuals/95d3a1d763fba254.json"},{"name":"Hedged requests","summary":"A delayed duplicate goes to another replica and the first valid response wins.","tradeoff":"Consumes extra capacity and requires safe cancellation.","visualPath":"../assets/data/system-design-visuals/2b4b8ab992d5cf15.json"},{"name":"Request cancellation","summary":"Callers propagate that a result is no longer needed so downstream work can stop safely.","tradeoff":"Committed effects may still complete after cancellation.","visualPath":"../assets/data/system-design-visuals/b5c8ab9eec876c85.json"}]},{"title":"Overload and isolation","concepts":[{"name":"Bulkheads","summary":"Separate resource pools prevent one dependency, tenant, or workload from exhausting all capacity.","tradeoff":"Reserved capacity can sit idle.","visualPath":"../assets/data/system-design-visuals/9ef85f78ec588303.json"},{"name":"Load shedding","summary":"Excess or low-priority work is rejected before queues and dependencies collapse.","tradeoff":"Intentional rejection preserves successful traffic.","visualPath":"../assets/data/system-design-visuals/86b8ca279f12ddac.json"},{"name":"Backpressure","summary":"Downstream saturation signals upstream stages to slow, block, or reject production.","tradeoff":"Pressure can propagate into visible unavailability.","visualPath":"../assets/data/system-design-visuals/d7f99468be729d04.json"},{"name":"Rate limiting","summary":"Admission is bounded over time for a defined user, tenant, endpoint, or dependency scope.","tradeoff":"Global precision requires coordination.","visualPath":"../assets/data/system-design-visuals/8cade4e2774bbce6.json"},{"name":"Adaptive throttling","summary":"Admission limits adjust from latency, errors, queueing, or available concurrency.","tradeoff":"Unstable feedback can oscillate or overreact.","visualPath":"../assets/data/system-design-visuals/4156230da2da42f8.json"},{"name":"Admission control","summary":"Work is accepted only when capacity, priority, and deadline make success plausible.","tradeoff":"Requires trustworthy load signals and fairness policy.","visualPath":"../assets/data/system-design-visuals/05f8919c635fab38.json"},{"name":"Dependency isolation","summary":"Dedicated pools, queues, quotas, and failure policies stop one dependency from consuming shared resources.","tradeoff":"Isolation reduces pooling efficiency.","visualPath":"../assets/data/system-design-visuals/2b90df5b60f5aa0b.json"},{"name":"Cell-based architecture","summary":"Self-contained cells serve bounded traffic subsets so failures and deployments remain local.","tradeoff":"Multiplies capacity planning and operations.","visualPath":"../assets/data/system-design-visuals/6461246c6f01ecc2.json"},{"name":"Blast-radius reduction","summary":"Cells, staged rollout, quotas, and separate credentials limit how much one fault can affect.","tradeoff":"More boundaries increase management overhead.","visualPath":"../assets/data/system-design-visuals/6f976a5414243fc6.json"}]},{"title":"Failure policy and domains","concepts":[{"name":"Fail-fast","summary":"Invalid or unlikely-to-succeed work is rejected immediately before consuming scarce resources.","tradeoff":"Transiently recoverable requests may fail sooner.","visualPath":"../assets/data/system-design-visuals/d83dcf8efbb722cd.json"},{"name":"Fail-open","summary":"When a control dependency fails, the operation proceeds to preserve availability.","tradeoff":"Can weaken security, policy, or consistency.","visualPath":"../assets/data/system-design-visuals/e1515f033bbcef40.json"},{"name":"Fail-closed","summary":"When a control dependency fails, the operation is denied to preserve safety or security.","tradeoff":"Dependency failure becomes user-visible unavailability.","visualPath":"../assets/data/system-design-visuals/b704378a50f95927.json"},{"name":"Graceful degradation","summary":"Core functions continue while optional, expensive, or stale-tolerant features are reduced.","tradeoff":"Users receive limited functionality.","visualPath":"../assets/data/system-design-visuals/7aa93bec529bb5a3.json"},{"name":"Fault domains","summary":"Fault domains identify components likely to fail together, such as a rack, zone, power source, or control plane.","tradeoff":"Spreading across domains raises latency and cost.","visualPath":"../assets/data/system-design-visuals/4c0f01a0fdb76ec5.json"},{"name":"Failure domains","summary":"Failure domains define operational containment and recovery boundaries for correlated faults.","tradeoff":"More independent domains require more capacity and coordination.","visualPath":"../assets/data/system-design-visuals/63d23f7587ec0e88.json"}]}]},{"id":"resilience-patterns","title":"Resilience Patterns","intro":"Resilience patterns define how systems detect, contain, survive, and recover from failures.","groups":[{"title":"Redundancy modes","concepts":[{"name":"Active-active","summary":"Multiple sites serve traffic concurrently, providing capacity and rapid failover.","tradeoff":"Requires conflict handling, traffic steering, and enough spare capacity.","visualPath":"../assets/data/system-design-visuals/9104bac0db311580.json"},{"name":"Active-passive","summary":"One site serves while a passive site waits to take over.","tradeoff":"Simpler consistency, but standby capacity is underused and failover is slower.","visualPath":"../assets/data/system-design-visuals/73edfb67b3d95ddd.json"},{"name":"Hot standby","summary":"A fully synchronized standby is ready to serve immediately.","tradeoff":"Lowest recovery time at nearly full duplicate cost.","visualPath":"../assets/data/system-design-visuals/8fb8056f7eff4cf0.json"},{"name":"Warm standby","summary":"A partially provisioned, continuously updated standby scales up during recovery.","tradeoff":"Balances cost and recovery time but needs reliable automation.","visualPath":"../assets/data/system-design-visuals/2f3c652babb819b5.json"},{"name":"Cold standby","summary":"Infrastructure or data is restored only after a failure.","tradeoff":"Cheapest standby with the longest recovery time and highest restore risk.","visualPath":"../assets/data/system-design-visuals/d4a6cb61bde8399e.json"}]},{"title":"Detection and failover","concepts":[{"name":"Leader failover","summary":"A new leader is elected or promoted when the current leader becomes unavailable.","tradeoff":"Election pauses progress and stale leaders require fencing.","visualPath":"../assets/data/system-design-visuals/e8410b52605adc31.json"},{"name":"Automatic failover","summary":"Automation redirects service after health and safety conditions are met.","tradeoff":"Bad detection can trigger unnecessary failover or split brain.","visualPath":"../assets/data/system-design-visuals/e270356e3ffda48a.json"},{"name":"Health checking","summary":"Synthetic or dependency-aware probes determine whether an instance can safely receive traffic.","tradeoff":"Shallow checks miss failures; deep checks can amplify dependency outages.","visualPath":"../assets/data/system-design-visuals/93f02926a0aa8de8.json"},{"name":"Heartbeats","summary":"Components periodically signal liveness so missed signals can trigger suspicion.","tradeoff":"Intervals trade detection speed against traffic and false positives.","visualPath":"../assets/data/system-design-visuals/eba24f35a83e7c69.json"},{"name":"Failure detection","summary":"A detector infers failed or unreachable members from timeouts, heartbeats, and quorum evidence.","tradeoff":"In asynchronous networks, failure cannot be distinguished perfectly from delay.","visualPath":"../assets/data/system-design-visuals/93196323f011a00d.json"}]},{"title":"Recovery objectives","concepts":[{"name":"Disaster recovery","summary":"Disaster recovery restores service after region-scale or correlated loss using tested people, data, and infrastructure procedures.","tradeoff":"Cross-region readiness adds cost and operational complexity.","visualPath":"../assets/data/system-design-visuals/a71135352e859ecd.json"},{"name":"RPO","summary":"Recovery Point Objective is the maximum acceptable amount of data loss measured in time.","tradeoff":"Lower RPO requires more frequent or synchronous replication.","visualPath":"../assets/data/system-design-visuals/c688873f8c88a596.json"},{"name":"RTO","summary":"Recovery Time Objective is the maximum acceptable time to restore service.","tradeoff":"Lower RTO requires pre-provisioning, automation, and frequent drills.","visualPath":"../assets/data/system-design-visuals/a87718cd21867342.json"},{"name":"Backup/restore","summary":"Backups create independent recoverable copies; restore procedures prove they are usable.","tradeoff":"Backup success is meaningless without restore testing and retention controls.","visualPath":"../assets/data/system-design-visuals/1f7631721f714cc5.json"},{"name":"Point-in-time recovery","summary":"Point-in-time recovery replays logs from a base backup to a chosen moment before corruption or error.","tradeoff":"Needs complete ordered logs and can take substantial replay time.","visualPath":"../assets/data/system-design-visuals/705d58d38623b0ae.json"}]},{"title":"Resilience validation","concepts":[{"name":"Chaos engineering","summary":"Controlled experiments test whether the system preserves stated invariants during realistic failures.","tradeoff":"Experiments need blast-radius controls, observability, and abort conditions.","visualPath":"../assets/data/system-design-visuals/3229b5ba6089ed80.json"},{"name":"Fault injection","summary":"Fault injection deliberately introduces latency, errors, loss, or resource exhaustion at a chosen boundary.","tradeoff":"Unrepresentative faults create false confidence; uncontrolled faults cause harm.","visualPath":"../assets/data/system-design-visuals/eadc5287fb2659ff.json"}]}]},{"id":"rate-limiting-traffic-management","title":"Rate Limiting & Traffic Management","intro":"Traffic management meters demand, preserves fairness, and protects finite downstream capacity.","groups":[{"title":"Rate algorithms","concepts":[{"name":"Token bucket","summary":"Tokens refill at a fixed rate and each admitted request consumes one, allowing bounded bursts.","tradeoff":"Distributed buckets need coordinated or approximate state.","visualPath":"../assets/data/system-design-visuals/cb98b129cb4fc181.json"},{"name":"Leaky bucket","summary":"Queued work drains at a steady rate, smoothing bursts into predictable output.","tradeoff":"Queues add latency and overflow still requires rejection.","visualPath":"../assets/data/system-design-visuals/f67aa567aa5df441.json"},{"name":"Fixed window","summary":"Requests are counted in discrete time windows and rejected after the limit.","tradeoff":"Boundary bursts can allow nearly twice the intended rate.","visualPath":"../assets/data/system-design-visuals/bf300442e0209980.json"},{"name":"Sliding window","summary":"A rolling log counts requests in the exact preceding interval.","tradeoff":"Accurate but expensive in memory and per-request operations.","visualPath":"../assets/data/system-design-visuals/ca82a02c56b70860.json"},{"name":"Sliding window counter","summary":"Adjacent fixed-window counters are weighted to approximate a rolling window.","tradeoff":"Cheaper than logs but only approximate near boundaries.","visualPath":"../assets/data/system-design-visuals/9fe231f56e70aa92.json"}]},{"title":"Distributed scope","concepts":[{"name":"Distributed rate limiting","summary":"Limiter state is shared or partitioned across service instances to enforce one policy.","tradeoff":"Coordination raises latency; local approximation can overshoot.","visualPath":"../assets/data/system-design-visuals/30b7ef501a2fdc32.json"},{"name":"Global rate limiting","summary":"A global limiter caps aggregate traffic across regions or clusters.","tradeoff":"Strong global precision conflicts with low latency and partition availability.","visualPath":"../assets/data/system-design-visuals/b59b3ae918e28f51.json"},{"name":"Per-user limits","summary":"Usage is metered by authenticated user to contain abuse and ensure fairness.","tradeoff":"Identity fan-out and shared accounts complicate policy.","visualPath":"../assets/data/system-design-visuals/4bc4b6df272a1a5a.json"},{"name":"Per-tenant limits","summary":"A tenant receives an aggregate budget across its users and workloads.","tradeoff":"Large tenants may need internal fairness and burst allowances.","visualPath":"../assets/data/system-design-visuals/330fcba76ebd8a88.json"},{"name":"Per-IP limits","summary":"Traffic is limited by source IP when stronger identity is absent or as an abuse signal.","tradeoff":"NAT penalizes many users together and attackers can rotate addresses.","visualPath":"../assets/data/system-design-visuals/118274eb8db0cb53.json"},{"name":"Hierarchical rate limiting","summary":"A request must satisfy nested budgets such as global, tenant, user, and endpoint limits.","tradeoff":"Multiple checks add state and can strand unused capacity at lower levels.","visualPath":"../assets/data/system-design-visuals/2127218fdb277395.json"}]},{"title":"Adaptive overload control","concepts":[{"name":"Adaptive rate limiting","summary":"Limits change from observed latency, errors, saturation, or downstream capacity.","tradeoff":"Unstable feedback loops can oscillate or overreact to noise.","visualPath":"../assets/data/system-design-visuals/10f166491a09b22f.json"},{"name":"Concurrency limiting","summary":"A cap on in-flight work bounds simultaneous pressure independently of request rate.","tradeoff":"A fixed cap underuses fast paths and overloads slow ones unless adaptive.","visualPath":"../assets/data/system-design-visuals/1de2541c4d84ebea.json"},{"name":"Load shedding","summary":"Low-value or excess work is rejected before saturation to protect useful traffic.","tradeoff":"Requires explicit priorities and a truthful rejection contract.","visualPath":"../assets/data/system-design-visuals/52b91f4efcc95a9d.json"},{"name":"Fair queuing","summary":"Separate flows receive turns so one source cannot monopolize service capacity.","tradeoff":"Flow classification and queue management add overhead.","visualPath":"../assets/data/system-design-visuals/65f5865265b322ec.json"},{"name":"Weighted fair queuing","summary":"Flows receive service proportional to configured weights while retaining isolation.","tradeoff":"Weights encode policy and can starve low-weight traffic if misconfigured.","visualPath":"../assets/data/system-design-visuals/ecca565d03162a32.json"}]}]},{"id":"distributed-scheduling","title":"Distributed Scheduling","intro":"Distributed schedulers assign durable work across workers while preserving ownership and recovery semantics.","groups":[{"title":"Scheduler architecture","concepts":[{"name":"Distributed job scheduler","summary":"A distributed job scheduler persists jobs, assigns runnable work, and recovers assignments after failures.","tradeoff":"Coordination and durable state become control-plane bottlenecks.","visualPath":"../assets/data/system-design-visuals/fc3a2b4c73479d7e.json"},{"name":"Leader-based scheduling","summary":"One elected leader makes placement decisions for a scheduling epoch.","tradeoff":"Simple ordering but leader failure pauses decisions and requires fencing.","visualPath":"../assets/data/system-design-visuals/6a96c1ab981445d3.json"},{"name":"Work stealing","summary":"Idle workers pull tasks from busier workers or partitions to rebalance execution.","tradeoff":"Stealing adds coordination and can hurt data locality.","visualPath":"../assets/data/system-design-visuals/def0d17378f0dc21.json"},{"name":"Task queues","summary":"Durable queues decouple task submission from worker execution and support retries.","tradeoff":"Delivery is commonly at least once, so effects must tolerate duplicates.","visualPath":"../assets/data/system-design-visuals/2fe6b17557f3c97f.json"},{"name":"Priority scheduling","summary":"Runnable work is ordered by business priority, deadline, or resource class.","tradeoff":"Strict priority can starve lower classes without aging or quotas.","visualPath":"../assets/data/system-design-visuals/ee3e5e51b103de12.json"}]},{"title":"Timing and retry","concepts":[{"name":"Delayed execution","summary":"Tasks remain durable but ineligible until a specified time or condition.","tradeoff":"Clock skew and large timer sets complicate precise wake-up.","visualPath":"../assets/data/system-design-visuals/acc428aa223fa184.json"},{"name":"Retry scheduling","summary":"Failed tasks are rescheduled with bounded attempts, backoff, jitter, and error classification.","tradeoff":"Retries amplify persistent failures and delay poison-task handling.","visualPath":"../assets/data/system-design-visuals/0f3aff995188fc9c.json"},{"name":"Cron/distributed cron","summary":"Recurring schedules are materialized once per interval despite replicated scheduler instances.","tradeoff":"Missed ticks, duplicate triggers, time zones, and clock changes need policy.","visualPath":"../assets/data/system-design-visuals/194a64c256ffc0df.json"}]},{"title":"Ownership and scale","concepts":[{"name":"Lease-based workers","summary":"Workers hold expiring leases for tasks and renew them while making progress.","tradeoff":"Expired owners may still act, so protected writes need fencing or idempotency.","visualPath":"../assets/data/system-design-visuals/9ca461ce41f8f094.json"},{"name":"Heartbeat-based ownership","summary":"Periodic progress signals keep ownership alive and expose abandoned tasks for reassignment.","tradeoff":"Detection speed trades against heartbeat load and false expiry.","visualPath":"../assets/data/system-design-visuals/5efbe80b49165e67.json"},{"name":"Sharded schedulers","summary":"Schedulers own disjoint job shards so decision throughput scales horizontally.","tradeoff":"Shard movement and hot shards complicate balancing and failover.","visualPath":"../assets/data/system-design-visuals/8205612103491e71.json"},{"name":"Scheduler partitioning","summary":"Jobs are mapped to scheduler partitions by tenant, key, or workflow locality.","tradeoff":"The partition key determines skew and cross-partition coordination cost.","visualPath":"../assets/data/system-design-visuals/7db34952c98f1490.json"}]},{"title":"Execution semantics","concepts":[{"name":"Exactly-once job execution","summary":"One logical outcome is achieved through transactional claims or deduplicated side effects despite retries.","tradeoff":"End-to-end exactly once is costly and often impossible across external systems.","visualPath":"../assets/data/system-design-visuals/a0bfeb87e6c476d7.json"},{"name":"Idempotent jobs","summary":"Repeated execution with the same job identity produces the same logical result.","tradeoff":"Deduplication state and non-idempotent downstream effects still need handling.","visualPath":"../assets/data/system-design-visuals/92bdc1a9cad421f1.json"},{"name":"Workflow engines","summary":"Workflow engines persist multi-step state, dependencies, timers, retries, and compensation.","tradeoff":"Durability simplifies recovery but couples applications to workflow semantics.","visualPath":"../assets/data/system-design-visuals/03f7041bdeecf777.json"}]}]},{"id":"storage-systems","title":"Storage Systems","intro":"Storage engines organize durable bytes to balance read, write, space, locality, and recovery costs.","groups":[{"title":"Core structures","concepts":[{"name":"LSM trees","summary":"LSM trees buffer sorted writes in memory and flush immutable runs that are merged later.","tradeoff":"Fast writes trade for read, space, and compaction amplification.","visualPath":"../assets/data/system-design-visuals/eb9f80c1be644f0c.json"},{"name":"B-trees","summary":"B-trees keep sorted keys in balanced, page-sized nodes for logarithmic reads and updates.","tradeoff":"Random in-place writes and page splits can limit write throughput.","visualPath":"../assets/data/system-design-visuals/096d1dfc2c97826e.json"},{"name":"SSTables","summary":"SSTables are immutable sorted key-value files with indexes and metadata for efficient range access.","tradeoff":"Reads may consult multiple files until compaction consolidates them.","visualPath":"../assets/data/system-design-visuals/e005820ed6852f26.json"},{"name":"Write-ahead logs","summary":"A write-ahead log durably records mutations before mutable state is acknowledged.","tradeoff":"Log sync adds latency and replay time grows without checkpoints.","visualPath":"../assets/data/system-design-visuals/88836465d3c7f62a.json"},{"name":"Memtables","summary":"Memtables hold recent sorted writes in memory before immutable flush.","tradeoff":"Memory is bounded, and unflushed data relies on the write-ahead log.","visualPath":"../assets/data/system-design-visuals/75604355ce836062.json"},{"name":"Compaction","summary":"Compaction merges sorted files, removes obsolete versions, and restores storage-level invariants.","tradeoff":"Consumes I/O and CPU and can create latency spikes.","visualPath":"../assets/data/system-design-visuals/29824bda87e47d36.json"},{"name":"Bloom filters","summary":"A Bloom filter probabilistically proves many keys are absent without reading storage.","tradeoff":"False positives remain and filters consume memory; false negatives are forbidden.","visualPath":"../assets/data/system-design-visuals/9497161553513759.json"}]},{"title":"Indexes","concepts":[{"name":"Indexing","summary":"Indexing builds auxiliary structures that map query keys to records or storage locations.","tradeoff":"Improves reads while adding storage, write amplification, and freshness lag.","visualPath":"../assets/data/system-design-visuals/457275655c05c288.json"},{"name":"Secondary indexes","summary":"Secondary indexes support lookup by non-primary attributes.","tradeoff":"Distributed maintenance and uniqueness require coordination or eventual repair.","visualPath":"../assets/data/system-design-visuals/4836dad8cef745bc.json"},{"name":"Inverted indexes","summary":"Inverted indexes map terms or features to postings lists of matching documents.","tradeoff":"Text analysis and updates add substantial storage and write cost.","visualPath":"../assets/data/system-design-visuals/d3841d36bdd62f90.json"},{"name":"Sparse indexes","summary":"Sparse indexes store entries for selected block boundaries rather than every row.","tradeoff":"Compact and cache-friendly but require scanning within the located block.","visualPath":"../assets/data/system-design-visuals/e2bdeb8183edb0fc.json"},{"name":"Covering indexes","summary":"A covering index contains every field needed by a query, avoiding base-record reads.","tradeoff":"Larger indexes increase write and storage costs.","visualPath":"../assets/data/system-design-visuals/f4aee196d9ec02fb.json"},{"name":"Partition indexes","summary":"Partition indexes map partition keys or ranges to physical owners and locations.","tradeoff":"Rebalancing requires versioned routing and careful cutover.","visualPath":"../assets/data/system-design-visuals/4457cd6d468d5dbb.json"}]},{"title":"Physical layouts","concepts":[{"name":"Columnar storage","summary":"Columnar storage keeps values by column, enabling compression and scans over selected fields.","tradeoff":"Point updates and full-row reconstruction are comparatively expensive.","visualPath":"../assets/data/system-design-visuals/687de96a94b7451f.json"},{"name":"Row-oriented storage","summary":"Row-oriented storage co-locates all fields of a record for efficient point reads and writes.","tradeoff":"Analytical scans read unnecessary columns and compress less effectively.","visualPath":"../assets/data/system-design-visuals/852a7175dce47b48.json"},{"name":"Log-structured storage","summary":"Log-structured storage appends new versions sequentially and reorganizes data asynchronously.","tradeoff":"Requires garbage collection or compaction and indirect reads.","visualPath":"../assets/data/system-design-visuals/34e736d85fc66de3.json"}]},{"title":"Storage services","concepts":[{"name":"Object storage","summary":"Object storage addresses whole blobs by key with metadata and massive namespace scale.","tradeoff":"Higher latency and whole-object operations make random mutation inefficient.","visualPath":"../assets/data/system-design-visuals/4fe9ea6c5d6e952f.json"},{"name":"Block storage","summary":"Block storage exposes low-level fixed-size blocks for filesystems and databases.","tradeoff":"Shared access and higher-level consistency must be built above it.","visualPath":"../assets/data/system-design-visuals/5e09e189044a7acd.json"},{"name":"Distributed filesystems","summary":"Distributed filesystems provide shared file semantics across replicated storage nodes.","tradeoff":"Metadata coordination, small files, and cross-node consistency can bottleneck scale.","visualPath":"../assets/data/system-design-visuals/63d53d23a7ec572f.json"}]}]},{"id":"database-distributed-system-concepts","title":"Database Distributed-System Concepts","intro":"Distributed databases coordinate data placement, replication, consistency, and online evolution.","groups":[{"title":"Topology and placement","concepts":[{"name":"Primary/replica","summary":"One primary orders writes while replicas copy its log and often serve reads.","tradeoff":"Primary failure needs promotion; asynchronous replicas can lag or lose acknowledged writes.","visualPath":"../assets/data/system-design-visuals/1291bc28497a287b.json"},{"name":"Leaderless databases","summary":"Clients coordinate reads and writes across replicas without one permanent write leader.","tradeoff":"Conflict resolution, repair, and quorum semantics become client-visible complexity.","visualPath":"../assets/data/system-design-visuals/1c039fe534235526.json"},{"name":"Distributed SQL","summary":"Distributed SQL combines relational queries and transactions with partitioned, replicated storage.","tradeoff":"Cross-shard coordination raises latency and query planning complexity.","visualPath":"../assets/data/system-design-visuals/8033dce0fca13fd4.json"},{"name":"Distributed transactions","summary":"Distributed transactions coordinate one atomic outcome across multiple resources or shards.","tradeoff":"Commit protocols add latency, coupling, and failure recovery states.","visualPath":"../assets/data/system-design-visuals/16bc373eecf32bb3.json"},{"name":"Sharding","summary":"Sharding partitions records across nodes by key or range to scale storage and throughput.","tradeoff":"Hot keys and cross-shard operations can dominate performance.","visualPath":"../assets/data/system-design-visuals/9785f57663d900f4.json"},{"name":"Replication","summary":"Replication maintains multiple copies for durability, availability, and read locality.","tradeoff":"Copy synchronization trades write latency against staleness and failover loss.","visualPath":"../assets/data/system-design-visuals/675d2cc225c6c12a.json"},{"name":"Consistent hashing","summary":"Consistent hashing maps keys to owners while minimizing movement when membership changes.","tradeoff":"It loses range locality and still needs virtual nodes or weighting for balance.","visualPath":"../assets/data/system-design-visuals/0e0247b98e647bff.json"}]},{"title":"Consistency and skew","concepts":[{"name":"Quorum","summary":"A quorum is an intersecting subset of replicas used to make or observe authoritative decisions.","tradeoff":"Larger quorums improve overlap but increase latency and reduce availability.","visualPath":"../assets/data/system-design-visuals/8082658bfd3a20eb.json"},{"name":"Read/write consistency","summary":"Read and write consistency levels define how many replicas participate and what versions may be observed.","tradeoff":"Stronger levels require more coordination and tolerate fewer failures.","visualPath":"../assets/data/system-design-visuals/0d1d24c92f4eb13b.json"},{"name":"Hot partitions","summary":"Hot partitions receive disproportionate traffic or data and cap system throughput at one shard.","tradeoff":"Salting or splitting improves balance but complicates queries and ordering.","visualPath":"../assets/data/system-design-visuals/bd7cd9459738b3dd.json"},{"name":"Read-after-write consistency","summary":"A client is guaranteed to observe its completed write on subsequent reads.","tradeoff":"Requires session routing, version tokens, or waiting for replica catch-up.","visualPath":"../assets/data/system-design-visuals/efbd539d8a9d2da5.json"}]},{"title":"Distributed indexes","concepts":[{"name":"Secondary indexes","summary":"Secondary indexes map non-primary attributes to records across partitioned data.","tradeoff":"Updates can be asynchronous and multi-shard queries require fan-out.","visualPath":"../assets/data/system-design-visuals/8fff1c1fbb7e24a7.json"},{"name":"Global indexes","summary":"A global index spans all data partitions and routes an indexed lookup directly to matching records.","tradeoff":"Central or repartitioned maintenance creates coordination and availability costs.","visualPath":"../assets/data/system-design-visuals/9cc99b610d2684ac.json"},{"name":"Local indexes","summary":"A local index covers only data in its owning shard and is updated with that shard.","tradeoff":"Cheap local maintenance but global queries must fan out to every shard.","visualPath":"../assets/data/system-design-visuals/d0d121d537aeb36e.json"}]},{"title":"Online change","concepts":[{"name":"Online schema migration","summary":"Schema changes roll out through backward-compatible expand, migrate, and contract phases while traffic continues.","tradeoff":"Mixed-version operation extends complexity and cleanup time.","visualPath":"../assets/data/system-design-visuals/52d26c368bab9f6a.json"},{"name":"Online reindexing","summary":"A replacement index is built beside the live index, caught up, validated, and atomically switched.","tradeoff":"Temporarily doubles storage and write work.","visualPath":"../assets/data/system-design-visuals/4a06f04a136ac496.json"},{"name":"Backfills","summary":"Backfills populate new fields, indexes, or derived data from historical records in bounded batches.","tradeoff":"Can overload production and race with concurrent writes.","visualPath":"../assets/data/system-design-visuals/62f390fb4d5c59ef.json"},{"name":"Dual writes","summary":"Dual writes send one logical change to two representations during migration.","tradeoff":"Without atomicity or reconciliation, partial success causes divergence.","visualPath":"../assets/data/system-design-visuals/c92e1026d5c67847.json"}]}]},{"id":"streaming-real-time-processing","title":"Streaming & Real-Time Processing","intro":"Streaming systems process unbounded, reordered event flows with explicit time, state, and recovery semantics.","groups":[{"title":"Core processing","concepts":[{"name":"Stream processing","summary":"Stream processing continuously transforms unbounded event sequences as records arrive.","tradeoff":"Low latency requires managing ordering, state, and recovery continuously.","visualPath":"../assets/data/system-design-visuals/aaab6e7c4a8a9db4.json"},{"name":"Windowing","summary":"Windowing bounds an unending stream into finite groups for computation.","tradeoff":"Window choice controls latency, completeness, and retained state.","visualPath":"../assets/data/system-design-visuals/2cdb324dafe34528.json"},{"name":"Tumbling windows","summary":"Tumbling windows divide time into adjacent non-overlapping intervals.","tradeoff":"Simple and efficient but events near boundaries are separated.","visualPath":"../assets/data/system-design-visuals/27725c4a35c2e01b.json"},{"name":"Sliding windows","summary":"Sliding windows overlap and emit results at a configured slide interval.","tradeoff":"Overlap increases state and repeated computation.","visualPath":"../assets/data/system-design-visuals/944aea6a715aee47.json"},{"name":"Session windows","summary":"Session windows group activity separated by less than an inactivity gap.","tradeoff":"Window boundaries can change when late events bridge sessions.","visualPath":"../assets/data/system-design-visuals/0b1a24d479f06697.json"}]},{"title":"Event time","concepts":[{"name":"Watermarks","summary":"Watermarks estimate how complete event-time progress is across input partitions.","tradeoff":"Aggressive watermarks drop or revise more late data; conservative ones delay output.","visualPath":"../assets/data/system-design-visuals/edf0640d6418a833.json"},{"name":"Event time vs processing time","summary":"Event time describes when an event occurred; processing time describes when the system handled it.","tradeoff":"Event time is reproducible but needs timestamps, watermarks, and late-data policy.","visualPath":"../assets/data/system-design-visuals/b490270bc97d58cd.json"},{"name":"Late events","summary":"Late events arrive after the system has emitted or finalized their intended result window.","tradeoff":"Updating results improves accuracy but complicates downstream consumers.","visualPath":"../assets/data/system-design-visuals/230cbd0d4d60e264.json"},{"name":"Out-of-order events","summary":"Out-of-order events arrive in a sequence different from their logical or event-time order.","tradeoff":"Reordering requires buffers, versioning, or commutative operations.","visualPath":"../assets/data/system-design-visuals/3042d6b15b22078a.json"},{"name":"Event-time processing","summary":"Event-time processing computes results from event timestamps rather than arrival time.","tradeoff":"More accurate under delay but increases state and finalization latency.","visualPath":"../assets/data/system-design-visuals/fc62f44734612897.json"}]},{"title":"State and guarantees","concepts":[{"name":"Stateful stream processing","summary":"Operators retain keyed state across events for aggregates, joins, and patterns.","tradeoff":"State growth, redistribution, and recovery become first-class concerns.","visualPath":"../assets/data/system-design-visuals/cd078bcb2a23d8fd.json"},{"name":"Checkpointing","summary":"Checkpointing persists operator state and source progress so processing can resume consistently.","tradeoff":"Frequent checkpoints add I/O; infrequent ones increase recovery work.","visualPath":"../assets/data/system-design-visuals/e379df7afb79493d.json"},{"name":"Exactly-once processing","summary":"State and input progress commit consistently so replay does not change one logical result.","tradeoff":"External side effects still require transactional or idempotent sinks.","visualPath":"../assets/data/system-design-visuals/537cef95b54db101.json"},{"name":"Deduplication","summary":"Deduplication suppresses repeated events using stable identities and retained seen-state.","tradeoff":"Retention bounds mean very late duplicates may escape detection.","visualPath":"../assets/data/system-design-visuals/e0ea8943dbb07c26.json"},{"name":"Backpressure","summary":"Backpressure slows producers or upstream operators when downstream capacity is exhausted.","tradeoff":"Prevents collapse but increases latency and can propagate across the pipeline.","visualPath":"../assets/data/system-design-visuals/542f6c0579f5fb9b.json"},{"name":"Replay","summary":"Replay reprocesses retained events to recover, rebuild state, or apply new logic.","tradeoff":"Requires deterministic logic, versioned schemas, and controlled downstream effects.","visualPath":"../assets/data/system-design-visuals/9c080f42b37f6cd4.json"}]},{"title":"Streaming operations","concepts":[{"name":"Stream joins","summary":"Stream joins correlate records from multiple streams within keys and time bounds.","tradeoff":"Unbounded joins require unbounded state; late data affects completeness.","visualPath":"../assets/data/system-design-visuals/0d255f94da49691a.json"},{"name":"Stream aggregation","summary":"Stream aggregation incrementally updates summaries as events arrive.","tradeoff":"Non-associative operations and corrections complicate parallel execution.","visualPath":"../assets/data/system-design-visuals/4c88510f2112015c.json"},{"name":"Windowed aggregation","summary":"Windowed aggregation computes summaries for bounded event-time or processing-time windows.","tradeoff":"Results depend on watermark and late-event policy.","visualPath":"../assets/data/system-design-visuals/7362f9a7fc4d057b.json"},{"name":"CEP / Complex Event Processing","summary":"Complex Event Processing detects temporal patterns across sequences of related events.","tradeoff":"Pattern state can grow rapidly and overlapping matches are hard to reason about.","visualPath":"../assets/data/system-design-visuals/7bf56318e875e252.json"}]}]},{"id":"distributed-data-processing","title":"Distributed Data Processing","intro":"Distributed processing divides large datasets into parallel stages while controlling movement, skew, and recovery.","groups":[{"title":"Batch model","concepts":[{"name":"MapReduce","summary":"Map transforms partitions independently and reduce combines values grouped by key.","tradeoff":"Robust stage boundaries incur materialization and shuffle overhead.","visualPath":"../assets/data/system-design-visuals/81581ca11c1e9ade.json"},{"name":"Shuffle","summary":"Shuffle repartitions intermediate records across workers by key.","tradeoff":"Often dominates network, disk, and serialization cost.","visualPath":"../assets/data/system-design-visuals/d24a4650203edaf9.json"},{"name":"Partitioning","summary":"Partitioning assigns records to parallel tasks by key, range, or input split.","tradeoff":"Poor keys create skew and expensive cross-partition work.","visualPath":"../assets/data/system-design-visuals/2f35fb7ed6aca3bf.json"},{"name":"Distributed aggregation","summary":"Distributed aggregation combines partial summaries from many partitions into a final result.","tradeoff":"Correct parallelization requires associative, mergeable state or extra coordination.","visualPath":"../assets/data/system-design-visuals/d5cfcbbed5861dd3.json"},{"name":"Combiners","summary":"Combiners perform local partial reduction before shuffle to reduce transferred data.","tradeoff":"Safe only for operations whose partial results can be merged correctly.","visualPath":"../assets/data/system-design-visuals/fe022dd90a6ddea9.json"},{"name":"Map-side aggregation","summary":"Map-side aggregation pre-aggregates records within an input task before repartitioning.","tradeoff":"Uses mapper memory and helps little when local keys are unique.","visualPath":"../assets/data/system-design-visuals/ecf1d73911292473.json"},{"name":"Reduce-side aggregation","summary":"Reduce-side aggregation combines all values for a key after shuffle.","tradeoff":"Complete grouping is flexible but pays full network movement.","visualPath":"../assets/data/system-design-visuals/82cd236a3062dccf.json"}]},{"title":"Distributed joins","concepts":[{"name":"Distributed joins","summary":"Distributed joins correlate partitioned datasets by moving or co-locating matching keys.","tradeoff":"Data movement, skew, and intermediate size dominate cost.","visualPath":"../assets/data/system-design-visuals/b1709aba2fcbeb0f.json"},{"name":"Broadcast joins","summary":"A small relation is copied to every worker so the large relation stays local.","tradeoff":"Fails when the broadcast side exceeds worker memory or network budget.","visualPath":"../assets/data/system-design-visuals/99b88af224afcf32.json"},{"name":"Hash joins","summary":"Inputs are partitioned or indexed by join-key hash and matching buckets are compared.","tradeoff":"Skew causes oversized buckets and spills.","visualPath":"../assets/data/system-design-visuals/5b6660632b7a9cd0.json"},{"name":"Sort-merge joins","summary":"Both inputs are sorted by key and scanned together to produce matches.","tradeoff":"Sorting is expensive but supports large inputs and range ordering.","visualPath":"../assets/data/system-design-visuals/9b570ea171de468c.json"}]},{"title":"Placement and tails","concepts":[{"name":"Data locality","summary":"Tasks run near their input blocks to reduce network transfer and improve throughput.","tradeoff":"Waiting for locality can delay scheduling and reduce utilization.","visualPath":"../assets/data/system-design-visuals/f7e46bc7859646af.json"},{"name":"Skew handling","summary":"Skew handling detects heavy keys or partitions and splits, salts, or isolates their work.","tradeoff":"Extra stages and merge logic complicate execution.","visualPath":"../assets/data/system-design-visuals/52dba0396ad04a96.json"},{"name":"Stragglers","summary":"Stragglers are unusually slow tasks that determine a stage completion tail.","tradeoff":"Root causes vary across skew, contention, hardware, and retries.","visualPath":"../assets/data/system-design-visuals/871134dcd29c2ea2.json"},{"name":"Speculative execution","summary":"Duplicate copies of slow tasks race and the first valid result wins.","tradeoff":"Consumes extra capacity and does not fix shared bottlenecks.","visualPath":"../assets/data/system-design-visuals/75837016ac32f559.json"},{"name":"Checkpointing","summary":"Checkpointing persists intermediate state or progress to limit recomputation after failure.","tradeoff":"Storage and coordination overhead trade against recovery speed.","visualPath":"../assets/data/system-design-visuals/a5ae7b07b71e28ec.json"}]}]},{"id":"search-retrieval","title":"Search & Retrieval","intro":"Search systems build distributed lexical and vector indexes, retrieve candidates, and rank them within a latency budget.","groups":[{"title":"Lexical retrieval","concepts":[{"name":"Inverted index","summary":"An inverted index maps each term to postings for documents containing it.","tradeoff":"Fast retrieval costs storage, analysis complexity, and update amplification.","visualPath":"../assets/data/system-design-visuals/b11ad1decb64e8f1.json"},{"name":"Forward index","summary":"A forward index maps each document to its terms or features.","tradeoff":"Useful for document processing but inefficient for corpus-wide term lookup.","visualPath":"../assets/data/system-design-visuals/a3ceb2f98a823c2f.json"},{"name":"TF-IDF","summary":"TF-IDF weights terms by frequency within a document and rarity across the corpus.","tradeoff":"Simple and interpretable but weak on term saturation and document length.","visualPath":"../assets/data/system-design-visuals/2d11221d7401fce5.json"},{"name":"BM25","summary":"BM25 ranks lexical matches using saturated term frequency, inverse document frequency, and length normalization.","tradeoff":"Requires tuning and cannot directly capture semantic similarity.","visualPath":"../assets/data/system-design-visuals/0f9a318b1eee6c90.json"}]},{"title":"Distributed query path","concepts":[{"name":"Sharded search","summary":"The corpus index is partitioned across shards so storage and query work scale horizontally.","tradeoff":"Global relevance and top results require cross-shard merging.","visualPath":"../assets/data/system-design-visuals/1ab1e8df71419e6d.json"},{"name":"Scatter-gather search","summary":"A coordinator scatters a query to shards and gathers partial top results.","tradeoff":"Fan-out amplifies tail latency and partial failures.","visualPath":"../assets/data/system-design-visuals/a2a88cba27cce0b0.json"},{"name":"Query fan-out","summary":"One logical query expands into requests to multiple index partitions or services.","tradeoff":"More fan-out improves coverage but multiplies cost and failure probability.","visualPath":"../assets/data/system-design-visuals/0392e9ac449ab569.json"},{"name":"Query routing","summary":"Query routing selects only shards or replicas likely to contain relevant results.","tradeoff":"Routing metadata can be stale and mistaken pruning reduces recall.","visualPath":"../assets/data/system-design-visuals/3b0f6bb36da74590.json"},{"name":"Search index replication","summary":"Index replicas serve queries and provide availability while ingest keeps versions convergent.","tradeoff":"Replication increases storage and may expose stale index versions.","visualPath":"../assets/data/system-design-visuals/e97e011004a9356d.json"}]},{"title":"Index lifecycle","concepts":[{"name":"Index building","summary":"Index building analyzes source documents and creates searchable postings, features, and segments.","tradeoff":"Full builds consume substantial compute, storage, and cutover coordination.","visualPath":"../assets/data/system-design-visuals/ea602e2a59fa8a05.json"},{"name":"Incremental indexing","summary":"Incremental indexing applies document changes without rebuilding the full index.","tradeoff":"Frequent small segments need merging and deletion handling.","visualPath":"../assets/data/system-design-visuals/23c5e5c455ac1ede.json"},{"name":"Near-real-time indexing","summary":"Near-real-time indexing exposes recent updates after a short refresh interval.","tradeoff":"Faster refresh increases segment churn and query overhead.","visualPath":"../assets/data/system-design-visuals/fe182e853dd3a2a6.json"}]},{"title":"Ranking and top results","concepts":[{"name":"Ranking","summary":"Ranking scores candidates using lexical, semantic, quality, freshness, and business signals.","tradeoff":"Better models add latency, opacity, and feedback-loop risk.","visualPath":"../assets/data/system-design-visuals/4bd06eba63caa019.json"},{"name":"Top-K retrieval","summary":"Top-K retrieval finds only the highest-scoring K candidates without fully sorting all matches.","tradeoff":"Distributed merging needs shard over-fetch to preserve global quality.","visualPath":"../assets/data/system-design-visuals/efb27b80566ec50f.json"}]},{"title":"Vector retrieval","concepts":[{"name":"Approximate nearest neighbor (ANN)","summary":"ANN searches vector space for close candidates while avoiding an exhaustive scan.","tradeoff":"Trades recall and determinism for latency and memory efficiency.","visualPath":"../assets/data/system-design-visuals/b9fcdcacbe5da0fb.json"},{"name":"HNSW","summary":"HNSW uses a layered navigable proximity graph for high-recall vector search.","tradeoff":"Strong query performance requires substantial memory and expensive updates.","visualPath":"../assets/data/system-design-visuals/d48caa495b75264b.json"},{"name":"IVF","summary":"IVF clusters vectors into coarse cells and searches only selected cells at query time.","tradeoff":"Probe count trades latency for recall, and cluster imbalance hurts performance.","visualPath":"../assets/data/system-design-visuals/a14549defbafac72.json"},{"name":"Vector indexes","summary":"Vector indexes organize embeddings for similarity retrieval using exact or approximate structures.","tradeoff":"Embedding drift, filtering, memory, and rebuild cost complicate operation.","visualPath":"../assets/data/system-design-visuals/143957e0aeb90472.json"}]}]},{"id":"distributed-algorithms","title":"Distributed Algorithms","intro":"Distributed algorithms provide traversal, optimization, coordination, and aggregation primitives at scale.","groups":[{"title":"Graph traversal and paths","concepts":[{"name":"BFS / DFS","summary":"BFS explores by distance layers while DFS follows a path before backtracking.","tradeoff":"BFS uses more frontier memory; DFS lacks shortest-path guarantees.","visualPath":"../assets/data/system-design-visuals/11b9dd151b6aacfb.json"},{"name":"Dijkstra","summary":"Dijkstra finds shortest paths from a source when edge weights are nonnegative.","tradeoff":"Priority-queue coordination is costly to parallelize and negative edges are unsupported.","visualPath":"../assets/data/system-design-visuals/d110accab1735c0f.json"},{"name":"Bellman-Ford","summary":"Bellman-Ford repeatedly relaxes edges and supports negative weights while detecting negative cycles.","tradeoff":"More general but much slower than Dijkstra on large graphs.","visualPath":"../assets/data/system-design-visuals/69725ebfb306056e.json"}]},{"title":"Trees and ordering","concepts":[{"name":"Minimum spanning tree","summary":"A minimum spanning tree connects all vertices with minimum total edge weight and no cycles.","tradeoff":"Models connectivity cost, not shortest routes from a source.","visualPath":"../assets/data/system-design-visuals/020f6ba0148c65f1.json"},{"name":"Kruskal","summary":"Kruskal adds edges in weight order when they connect different components.","tradeoff":"Requires global edge ordering but parallel component checks can help.","visualPath":"../assets/data/system-design-visuals/8c92111535e67eeb.json"},{"name":"Prim","summary":"Prim grows one tree by repeatedly adding the cheapest edge leaving it.","tradeoff":"Efficient on dense graphs but frontier coordination can bottleneck distribution.","visualPath":"../assets/data/system-design-visuals/c51adf9cfea1dfba.json"},{"name":"Topological sort","summary":"Topological sort orders a directed acyclic graph so every dependency precedes its dependents.","tradeoff":"Cycles make the ordering impossible and must be detected.","visualPath":"../assets/data/system-design-visuals/6e990240d93ed6b9.json"},{"name":"Union-Find","summary":"Union-Find maintains disjoint sets with near-constant-time union and connectivity checks.","tradeoff":"Excellent for incremental merges but not deletions or rich component queries.","visualPath":"../assets/data/system-design-visuals/cb0f6bb358bfabe2.json"}]},{"title":"Coordination and dissemination","concepts":[{"name":"Consistent hashing","summary":"Consistent hashing assigns keys to changing members while minimizing remapping.","tradeoff":"Needs balancing techniques and provides no range locality.","visualPath":"../assets/data/system-design-visuals/944bdead7cb8198c.json"},{"name":"Gossip","summary":"Gossip disseminates state through randomized peer exchanges until replicas converge.","tradeoff":"Convergence is probabilistic and duplicate traffic is expected.","visualPath":"../assets/data/system-design-visuals/35e84a5adc13e1ee.json"},{"name":"Leader election","summary":"Leader election chooses one authority for an epoch among distributed participants.","tradeoff":"Partitions and pauses require quorum rules and fencing of stale leaders.","visualPath":"../assets/data/system-design-visuals/4331d30aff48e714.json"},{"name":"Distributed consensus","summary":"Distributed consensus lets a quorum agree on one value or ordered log despite crashes and delay.","tradeoff":"Adds coordination latency and stops making progress without quorum.","visualPath":"../assets/data/system-design-visuals/54cd354cb384a869.json"},{"name":"Distributed snapshots","summary":"A distributed snapshot captures a causally consistent global state without stopping all participants.","tradeoff":"In-flight messages and channel recording add protocol and storage cost.","visualPath":"../assets/data/system-design-visuals/d7b3303dcacbc27c.json"}]},{"title":"Parallel data algorithms","concepts":[{"name":"Distributed sorting","summary":"Distributed sorting range-partitions records, sorts partitions locally, and combines ordered outputs.","tradeoff":"Sampling errors create skew and repartitioning requires heavy shuffle.","visualPath":"../assets/data/system-design-visuals/7f1c7870b1ae1050.json"},{"name":"Distributed aggregation","summary":"Distributed aggregation merges partition-local summaries into a global result.","tradeoff":"Efficient trees require associative state and careful duplicate handling.","visualPath":"../assets/data/system-design-visuals/a4325f2cf52491a5.json"}]}]},{"id":"api-service-architecture","title":"API / Service Architecture","intro":"Route and evolve service traffic through explicit boundaries, policies, and rollout controls.","groups":[{"title":"Edge and routing","concepts":[{"name":"API Gateway","summary":"A managed edge entry point centralizes routing, authentication, quotas, and protocol adaptation.","tradeoff":"It can become a bottleneck or policy monolith.","visualPath":"../assets/data/system-design-visuals/4066c9a13120ef91.json"},{"name":"Reverse proxy","summary":"A reverse proxy terminates client connections and forwards requests to internal services.","tradeoff":"It adds a hop and shared failure point.","visualPath":"../assets/data/system-design-visuals/7540b2a862500f17.json"},{"name":"Load balancing","summary":"Load balancing spreads work across healthy instances to improve utilization and availability.","tradeoff":"Poor policies amplify hotspots and retries.","visualPath":"../assets/data/system-design-visuals/a09a201ca250cdcf.json"},{"name":"L4 vs L7 load balancing","summary":"L4 routes using transport metadata; L7 understands application protocols and request attributes.","tradeoff":"L7 enables richer policy but costs more processing.","visualPath":"../assets/data/system-design-visuals/8e422ef18ad24a8f.json"},{"name":"Service discovery","summary":"Service discovery maps logical service identities to current healthy endpoints.","tradeoff":"Stale registry data can misroute traffic.","visualPath":"../assets/data/system-design-visuals/857f877892537e57.json"},{"name":"Client-side load balancing","summary":"The client selects an endpoint from discovery data and applies local balancing policy.","tradeoff":"Every client must implement updates and resilience correctly.","visualPath":"../assets/data/system-design-visuals/286efbc80bf1075c.json"},{"name":"Server-side load balancing","summary":"A proxy or load balancer selects backends on behalf of clients.","tradeoff":"The shared tier adds latency and capacity risk.","visualPath":"../assets/data/system-design-visuals/5f44e72391bdf11b.json"},{"name":"Request routing","summary":"Routing selects a destination using path, identity, version, locality, or health.","tradeoff":"Complex rules become difficult to reason about.","visualPath":"../assets/data/system-design-visuals/8a1d48fdc69a41d2.json"}]},{"title":"Service networking","concepts":[{"name":"Service mesh","summary":"A service mesh standardizes transport security, telemetry, and traffic policy between services.","tradeoff":"It adds infrastructure and debugging complexity.","visualPath":"../assets/data/system-design-visuals/61f0659d10e696ac.json"},{"name":"Sidecars","summary":"Sidecars colocate networking or policy capabilities beside each workload instance.","tradeoff":"Per-instance proxies consume resources and obscure call paths.","visualPath":"../assets/data/system-design-visuals/a339c1e775d3dc16.json"},{"name":"North-south traffic","summary":"North-south traffic crosses the system boundary between external clients and internal services.","tradeoff":"Edge controls must scale without hiding internal failures.","visualPath":"../assets/data/system-design-visuals/82cdd2e97e9203ed.json"},{"name":"East-west traffic","summary":"East-west traffic flows among internal services and often dominates distributed call volume.","tradeoff":"Fan-out increases latency and failure amplification.","visualPath":"../assets/data/system-design-visuals/bbb68beff633bd9b.json"},{"name":"Control plane vs data plane","summary":"The control plane distributes desired state while the data plane serves high-volume requests.","tradeoff":"The data plane must remain safe with stale control state.","visualPath":"../assets/data/system-design-visuals/c8e0cc4567a6990b.json"},{"name":"Configuration distribution","summary":"Configuration distribution publishes versioned settings with validation, staged rollout, and rollback.","tradeoff":"Fast propagation increases blast radius.","visualPath":"../assets/data/system-design-visuals/1a96583490b34038.json"}]},{"title":"Progressive delivery","concepts":[{"name":"Traffic shadowing","summary":"Traffic shadowing mirrors requests to a non-authoritative path for realistic validation.","tradeoff":"Shadow paths must suppress side effects and protect data.","visualPath":"../assets/data/system-design-visuals/b1a5598abed4d1e6.json"},{"name":"Canary deployments","summary":"Canary deployments expose a new version to a small cohort before wider rollout.","tradeoff":"A poor cohort can miss systemic failures.","visualPath":"../assets/data/system-design-visuals/2247c6f7ecb5833e.json"},{"name":"Blue-green deployments","summary":"Blue-green deployments switch traffic between two complete environments.","tradeoff":"They require duplicate capacity and data compatibility.","visualPath":"../assets/data/system-design-visuals/91dbe428a51102ab.json"},{"name":"A/B routing","summary":"A/B routing assigns cohorts to variants to compare product or system outcomes.","tradeoff":"Cross-cohort effects can bias results.","visualPath":"../assets/data/system-design-visuals/95543d7376eda272.json"},{"name":"Feature flags","summary":"Feature flags separate code deployment from behavior exposure and support targeted rollback.","tradeoff":"Long-lived flags create combinatorial states.","visualPath":"../assets/data/system-design-visuals/b13ece1ddb5e11d5.json"}]}]},{"id":"realtime-connections","title":"Realtime Connections","intro":"Choose and operate client connection lifecycles for timely one-way or bidirectional updates.","groups":[{"title":"Connection models","concepts":[{"name":"Long polling","summary":"Long polling holds an HTTP request until an event or timeout, then the client reconnects immediately.","tradeoff":"Repeated requests and held connections consume gateway and server capacity.","visualPath":"../assets/data/system-design-visuals/79f1b60bfc05c962.json"},{"name":"Server-Sent Events (SSE)","summary":"SSE keeps one HTTP response open for a server-to-client event stream with built-in reconnect support.","tradeoff":"It is one-way and intermediaries must support long-lived streaming responses.","visualPath":"../assets/data/system-design-visuals/0e3a29bae0db9790.json"},{"name":"WebSockets","summary":"WebSockets upgrade HTTP to a persistent full-duplex framed connection for low-latency bidirectional messaging.","tradeoff":"Connection ownership, fan-out, backpressure, and recovery complicate horizontal scaling.","visualPath":"../assets/data/system-design-visuals/ca647cd1c5578792.json"}]}]},{"id":"distributed-identity-security","title":"Distributed Identity & Security","intro":"Carry verifiable identity and least authority across every service and trust boundary.","groups":[{"title":"Protocols and tokens","concepts":[{"name":"OAuth 2.0","summary":"OAuth 2.0 delegates scoped API access through resource-targeted access tokens.","tradeoff":"Security depends on flow choice and strict validation.","visualPath":"../assets/data/system-design-visuals/6dbcdf81fa4548c7.json"},{"name":"OIDC","summary":"OIDC adds authentication and identity claims to OAuth 2.0.","tradeoff":"ID tokens are not general API access tokens.","visualPath":"../assets/data/system-design-visuals/6d1fef6f47e4394b.json"},{"name":"JWT","summary":"A JWT carries signed claims that a recipient can validate locally.","tradeoff":"Claims remain stale until expiry.","visualPath":"../assets/data/system-design-visuals/5c1ee612f8781948.json"},{"name":"JWKS","summary":"JWKS publishes public verification keys identified by key IDs.","tradeoff":"Caching and rotation must handle overlap safely.","visualPath":"../assets/data/system-design-visuals/3ef156a12758b36a.json"},{"name":"Token introspection","summary":"Token introspection asks an authorization service whether an opaque token is active and what it means.","tradeoff":"It adds latency and availability coupling.","visualPath":"../assets/data/system-design-visuals/12b084433c70d081.json"},{"name":"Access-token validation","summary":"A resource validates signature, issuer, audience, lifetime, algorithm, and required claims.","tradeoff":"Validation policy must evolve without accepting unsafe tokens.","visualPath":"../assets/data/system-design-visuals/7917211a918845b8.json"},{"name":"Edge token validation","summary":"The edge rejects invalid tokens early while downstream services still enforce their own authorization.","tradeoff":"Edge-only trust creates bypass risk.","visualPath":"../assets/data/system-design-visuals/0b0c479cb7be5919.json"},{"name":"Token caching","summary":"Token caching reuses valid tokens or validation metadata until a safe refresh boundary.","tradeoff":"Caching delays revocation and claim changes.","visualPath":"../assets/data/system-design-visuals/61e1d038b0e3ab0c.json"},{"name":"Key rotation","summary":"Key rotation overlaps old and new verification keys to replace cryptographic material without downtime.","tradeoff":"Overlap temporarily broadens accepted keys.","visualPath":"../assets/data/system-design-visuals/1fa41565542c0761.json"},{"name":"Credential rotation","summary":"Credential rotation replaces secrets or certificates through staged issuance, activation, and retirement.","tradeoff":"Consumers must tolerate both versions during rollout.","visualPath":"../assets/data/system-design-visuals/b3610404004c8b01.json"},{"name":"Revocation","summary":"Revocation invalidates authority before normal expiry through state checks, lists, or short lifetimes.","tradeoff":"Immediate revocation requires coordination.","visualPath":"../assets/data/system-design-visuals/eb410bc025f4bec8.json"}]},{"title":"Workload identity and transport","concepts":[{"name":"Workload identity","summary":"Workload identity gives each service a short-lived, attestable principal instead of shared secrets.","tradeoff":"Bootstrap trust becomes critical infrastructure.","visualPath":"../assets/data/system-design-visuals/c0dde3098087fb8c.json"},{"name":"Workload identity federation","summary":"Workload identity federation exchanges trusted external assertions for local credentials without stored secrets.","tradeoff":"Issuer and subject mappings require strict governance.","visualPath":"../assets/data/system-design-visuals/47d107fb24b09948.json"},{"name":"SPIFFE","summary":"SPIFFE defines portable workload identity names and credential interfaces.","tradeoff":"Adoption still requires a trusted identity plane.","visualPath":"../assets/data/system-design-visuals/fe050e0a1c2e3f53.json"},{"name":"SPIRE","summary":"SPIRE implements SPIFFE identity issuance using node and workload attestation.","tradeoff":"Its servers and agents become security-critical.","visualPath":"../assets/data/system-design-visuals/7ccbcc47c1406abd.json"},{"name":"SVID","summary":"An SVID is a short-lived credential proving a SPIFFE workload identity.","tradeoff":"Frequent renewal must survive issuer outages.","visualPath":"../assets/data/system-design-visuals/d595f3b9f080bf64.json"},{"name":"mTLS","summary":"mTLS encrypts transport and authenticates both peers with certificates.","tradeoff":"It does not replace application authorization.","visualPath":"../assets/data/system-design-visuals/090b1e3e7464a8f5.json"},{"name":"PKI","summary":"PKI binds public keys to identities through certificate authorities and trust chains.","tradeoff":"Issuer compromise has a broad blast radius.","visualPath":"../assets/data/system-design-visuals/cd5558f16407d7a6.json"},{"name":"Certificate rotation","summary":"Certificate rotation renews identities with overlap, automation, and expiry monitoring.","tradeoff":"Broken renewal can cause fleet-wide outages.","visualPath":"../assets/data/system-design-visuals/6add78a9ceda6eb3.json"},{"name":"Service-to-service authentication","summary":"Service-to-service authentication verifies the calling workload at each hop.","tradeoff":"Identity infrastructure must be highly available.","visualPath":"../assets/data/system-design-visuals/b80dbf4415f68e22.json"},{"name":"Service-to-service authorization","summary":"Service-to-service authorization evaluates whether a workload may perform a specific resource action.","tradeoff":"Fine-grained policy adds latency and management cost.","visualPath":"../assets/data/system-design-visuals/0a4fbd77a3370ccf.json"}]},{"title":"Authorization policy","concepts":[{"name":"RBAC","summary":"RBAC assigns permissions to roles and principals to those roles.","tradeoff":"Context-rich systems suffer role explosion.","visualPath":"../assets/data/system-design-visuals/23d913214defc1ba.json"},{"name":"ABAC","summary":"ABAC evaluates actor, resource, action, and environment attributes.","tradeoff":"Flexible rules are harder to explain and cache.","visualPath":"../assets/data/system-design-visuals/95bd02106766429e.json"},{"name":"Policy engines","summary":"Policy engines evaluate centralized rules from explicit request context.","tradeoff":"Remote decisions add latency and dependency risk.","visualPath":"../assets/data/system-design-visuals/2b7148f3f67f3f03.json"},{"name":"Policy propagation","summary":"Policy propagation distributes versioned authorization state to enforcement points.","tradeoff":"Caches can enforce stale policy.","visualPath":"../assets/data/system-design-visuals/4912f9b452440d02.json"},{"name":"Distributed authorization","summary":"Distributed authorization keeps policy decisions consistent across independently deployed services.","tradeoff":"Consistency, latency, and availability compete.","visualPath":"../assets/data/system-design-visuals/0faa7324e50ef1cd.json"},{"name":"Zero Trust","summary":"Zero Trust requires explicit identity and authorization for every interaction regardless of network location.","tradeoff":"Continuous checks add operational dependencies.","visualPath":"../assets/data/system-design-visuals/5d90123cbf3d4361.json"},{"name":"Trust boundaries","summary":"Trust boundaries mark where data or identity changes assurance level and must be revalidated.","tradeoff":"More boundaries increase enforcement work.","visualPath":"../assets/data/system-design-visuals/b098b011f78f8a19.json"},{"name":"Auditability","summary":"Auditability records attributable identities, policy, resources, actions, and outcomes.","tradeoff":"Detailed audit data raises privacy and retention costs.","visualPath":"../assets/data/system-design-visuals/7bc1c830a354160a.json"}]},{"title":"Delegation and containment","concepts":[{"name":"Delegated identity","summary":"Delegated identity lets a workload act with narrowly bounded authority derived from another principal.","tradeoff":"Delegation chains complicate consent and audit.","visualPath":"../assets/data/system-design-visuals/e2d34fe835b30366.json"},{"name":"OBO","summary":"OBO exchanges a user token for a downstream token representing both user and calling service.","tradeoff":"Extra exchanges add latency and issuer dependence.","visualPath":"../assets/data/system-design-visuals/a37e6724f1f63b59.json"},{"name":"Confused deputy","summary":"A confused deputy uses its privilege for an untrusted caller without binding intent and target.","tradeoff":"Prevention requires explicit delegation and resource scoping.","visualPath":"../assets/data/system-design-visuals/ed66ed9a8388cead.json"},{"name":"Credential blast radius","summary":"Credential blast radius is the maximum authority and systems exposed by one compromised credential.","tradeoff":"Narrower credentials increase lifecycle overhead.","visualPath":"../assets/data/system-design-visuals/ef486ee73fe9f01a.json"}]}]},{"id":"observability-distributed-debugging","title":"Observability & Distributed Debugging","intro":"Correlate bounded telemetry across hops to explain user impact and distributed causality.","groups":[{"title":"Telemetry signals","concepts":[{"name":"Metrics","summary":"Metrics aggregate numeric behavior over dimensions and time for fast health detection.","tradeoff":"Aggregation hides individual request context.","visualPath":"../assets/data/system-design-visuals/dedd5d7e7efd007c.json"},{"name":"Logs","summary":"Logs capture structured discrete events with enough context for investigation.","tradeoff":"High volume increases cost and search noise.","visualPath":"../assets/data/system-design-visuals/72a72e0baa374e66.json"},{"name":"Distributed tracing","summary":"Distributed tracing links causal work across services as a tree or graph of spans.","tradeoff":"Instrumentation gaps produce incomplete traces.","visualPath":"../assets/data/system-design-visuals/396008de52b7ee85.json"},{"name":"OpenTelemetry","summary":"OpenTelemetry standardizes APIs, context, semantic conventions, and export for telemetry.","tradeoff":"Standard collection still requires careful schemas and sampling.","visualPath":"../assets/data/system-design-visuals/1637737f91a9cdfd.json"},{"name":"Correlation IDs","summary":"Correlation IDs connect related events when full parent-child tracing is unavailable.","tradeoff":"One ID cannot represent concurrency or causality.","visualPath":"../assets/data/system-design-visuals/306bc382d74ca78b.json"},{"name":"Trace IDs","summary":"Trace IDs identify all spans belonging to one distributed operation.","tradeoff":"They must not become unbounded metric labels.","visualPath":"../assets/data/system-design-visuals/263c3071ad447518.json"},{"name":"Span IDs","summary":"Span IDs identify individual units of work and their parent relationships.","tradeoff":"Missing propagation breaks the causal graph.","visualPath":"../assets/data/system-design-visuals/ac371de9c38f7e26.json"}]},{"title":"Sampling and measurement","concepts":[{"name":"Sampling","summary":"Sampling retains a representative subset of telemetry to control overhead and cost.","tradeoff":"Rare failures may be omitted.","visualPath":"../assets/data/system-design-visuals/aae834066b6975da.json"},{"name":"Tail-based sampling","summary":"Tail-based sampling decides after observing trace outcomes, retaining errors or slow requests preferentially.","tradeoff":"Collectors must buffer and coordinate trace state.","visualPath":"../assets/data/system-design-visuals/59c98870a532e2bf.json"},{"name":"RED metrics","summary":"RED metrics track request rate, errors, and duration for request-serving systems.","tradeoff":"They reveal symptoms rather than resource causes.","visualPath":"../assets/data/system-design-visuals/7a73a8bb63b35974.json"},{"name":"USE metrics","summary":"USE metrics track utilization, saturation, and errors for constrained resources.","tradeoff":"Healthy resources do not prove user success.","visualPath":"../assets/data/system-design-visuals/eac4016c6781a1d4.json"},{"name":"SLI / SLO / SLA","summary":"SLIs measure behavior, SLOs set internal targets, and SLAs attach external commitments.","tradeoff":"Bad indicators optimize the wrong outcome.","visualPath":"../assets/data/system-design-visuals/ce05859c0ff0bad0.json"},{"name":"Error budgets","summary":"Error budgets quantify allowable unreliability and guide release versus reliability investment.","tradeoff":"They require trusted measurement and enforcement.","visualPath":"../assets/data/system-design-visuals/e388466c69c6c87e.json"},{"name":"Cardinality management","summary":"Cardinality management bounds telemetry dimensions and keeps unique values out of aggregate indexes.","tradeoff":"Less dimensionality limits ad hoc slicing.","visualPath":"../assets/data/system-design-visuals/be55844eae501313.json"}]},{"title":"Distributed diagnosis","concepts":[{"name":"Dependency graphs","summary":"Dependency graphs show runtime service and resource relationships for critical-path analysis.","tradeoff":"Observed graphs omit dormant or unsampled paths.","visualPath":"../assets/data/system-design-visuals/e4b4a673b3b25aa8.json"},{"name":"Distributed profiling","summary":"Distributed profiling connects CPU, allocation, lock, and wall-time samples across request paths.","tradeoff":"Profiling adds overhead and sensitive detail.","visualPath":"../assets/data/system-design-visuals/a71f0c60887f9848.json"},{"name":"Anomaly detection","summary":"Anomaly detection identifies deviations from learned baselines across seasonality and dimensions.","tradeoff":"Model drift and noise create false alerts.","visualPath":"../assets/data/system-design-visuals/6928f994e8f19b9e.json"}]}]},{"id":"distributed-system-migration-patterns","title":"Distributed System Migration Patterns","intro":"Move systems through observable, compatible, and reversible coexistence states.","groups":[{"title":"Coexistence patterns","concepts":[{"name":"Strangler pattern","summary":"The Strangler pattern incrementally routes capabilities from a legacy system to a replacement.","tradeoff":"The coexistence layer can become permanent debt.","visualPath":"../assets/data/system-design-visuals/2a9d02e31ba72d9a.json"},{"name":"Dual writes","summary":"Dual writes update old and new stores while recording partial failures for repair.","tradeoff":"Without one transaction, divergence is inevitable.","visualPath":"../assets/data/system-design-visuals/0ae53cb4e52bfb6f.json"},{"name":"Dual reads","summary":"Dual reads compare or combine results from old and new systems during transition.","tradeoff":"They increase latency and load.","visualPath":"../assets/data/system-design-visuals/e8ed136658ed5efa.json"},{"name":"Shadow reads","summary":"Shadow reads query the target without using its response and compare it asynchronously.","tradeoff":"They can expose sensitive data and double read traffic.","visualPath":"../assets/data/system-design-visuals/410e7c5a20ee2066.json"},{"name":"Compatibility layers","summary":"Compatibility layers translate old contracts and semantics into the new model.","tradeoff":"Translation adds latency and another retirement task.","visualPath":"../assets/data/system-design-visuals/88ce249b6848cf25.json"}]},{"title":"Data movement","concepts":[{"name":"Backfill","summary":"Backfill copies historical data with stable partitions, checkpoints, throttling, and retries.","tradeoff":"It competes with production and races live updates.","visualPath":"../assets/data/system-design-visuals/145db8644a5b0c13.json"},{"name":"CDC migration","summary":"CDC migration streams committed source changes to keep a target synchronized during transfer.","tradeoff":"Ordering, deletes, and schema changes need explicit handling.","visualPath":"../assets/data/system-design-visuals/afbea3b1ff8d3a9d.json"},{"name":"Online migration","summary":"Online migration changes data or infrastructure while normal traffic continues.","tradeoff":"Safe coexistence lengthens the migration.","visualPath":"../assets/data/system-design-visuals/11316fe66cf9259b.json"},{"name":"Data reconciliation","summary":"Data reconciliation compares invariants, hashes, counts, and records, then repairs differences idempotently.","tradeoff":"Full comparison is expensive.","visualPath":"../assets/data/system-design-visuals/6b8877cf7cd20ca0.json"}]},{"title":"Compatibility and rollout","concepts":[{"name":"Expand-and-contract","summary":"Expand-and-contract adds compatible support, migrates all users, then removes the old form.","tradeoff":"Intermediate duplication spans multiple releases.","visualPath":"../assets/data/system-design-visuals/977d44b91193b91f.json"},{"name":"Versioned schemas","summary":"Versioned schemas let mixed producers and consumers interpret data intentionally.","tradeoff":"Every supported version adds maintenance cost.","visualPath":"../assets/data/system-design-visuals/635b0f1b180752ff.json"},{"name":"Rolling migration","summary":"Rolling migration updates nodes or partitions incrementally while mixed versions interoperate.","tradeoff":"Compatibility constrains new feature use.","visualPath":"../assets/data/system-design-visuals/39377f769f1e0f75.json"},{"name":"Incremental rollout","summary":"Incremental rollout expands exposure only after each cohort meets defined guardrails.","tradeoff":"More stages slow completion.","visualPath":"../assets/data/system-design-visuals/4718aeeaba7b76e3.json"},{"name":"Canary migration","summary":"Canary migration moves a small representative data or tenant cohort before the fleet.","tradeoff":"Cross-cohort interactions may hide defects.","visualPath":"../assets/data/system-design-visuals/00be89256ef01319.json"}]},{"title":"Authority transition","concepts":[{"name":"Cutover strategies","summary":"Cutover strategies define the exact routing, write authority, draining, and validation sequence.","tradeoff":"A hard cutover is simple but risky.","visualPath":"../assets/data/system-design-visuals/38da4fd84b8b3052.json"},{"name":"Rollback strategies","summary":"Rollback strategies preserve compatible code, data, and routing until recovery is proven.","tradeoff":"Rollback options increase temporary complexity and cost.","visualPath":"../assets/data/system-design-visuals/0cfb93a288e3b7df.json"}]}]},{"id":"consistency-conflict-patterns","title":"Consistency & Conflict Patterns","intro":"Detect concurrent versions and resolve them without violating the required consistency contract.","groups":[{"title":"Conflict selection","concepts":[{"name":"Last-write-wins","summary":"Last-write-wins selects the value with the greatest timestamp or deterministic version order.","tradeoff":"It can silently discard concurrent valid writes.","visualPath":"../assets/data/system-design-visuals/4231914c2d12d2c9.json"},{"name":"First-write-wins","summary":"First-write-wins preserves the earliest accepted value and rejects later competitors.","tradeoff":"It requires an authoritative ordering point.","visualPath":"../assets/data/system-design-visuals/9f078077b75ddfda.json"},{"name":"Version numbers","summary":"Version numbers expose update order and support conditional mutation or stale-write rejection.","tradeoff":"Independent writers need a shared or richer version scheme.","visualPath":"../assets/data/system-design-visuals/6cffa922b1dd7ae1.json"},{"name":"Vector clocks","summary":"Vector clocks distinguish causal order from concurrent versions using per-writer counters.","tradeoff":"Metadata grows with the writer set.","visualPath":"../assets/data/system-design-visuals/b528f9e98038a2f2.json"},{"name":"Conflict-free replicated data types","summary":"Conflict-free replicated data types merge concurrent state or operations algebraically to guarantee convergence.","tradeoff":"Available semantics and metadata can be restrictive.","visualPath":"../assets/data/system-design-visuals/d3203f3b0e3e40fe.json"},{"name":"Application-level conflict resolution","summary":"Application-level conflict resolution applies domain rules to merge, reject, or escalate concurrent values.","tradeoff":"Correct merge logic is domain-specific.","visualPath":"../assets/data/system-design-visuals/11cacd123ecd72a8.json"}]},{"title":"Replica repair","concepts":[{"name":"Read repair","summary":"Read repair detects divergent replicas during reads and propagates the selected value.","tradeoff":"Cold keys may remain divergent.","visualPath":"../assets/data/system-design-visuals/08697240ba277eb0.json"},{"name":"Anti-entropy","summary":"Anti-entropy compares replicas in the background and exchanges missing or conflicting ranges.","tradeoff":"Repair consumes bandwidth and converges gradually.","visualPath":"../assets/data/system-design-visuals/dba256660ab328c6.json"},{"name":"Merkle trees","summary":"Merkle trees summarize ranges hierarchically so replicas can locate differences efficiently.","tradeoff":"Maintaining trees adds compute and metadata.","visualPath":"../assets/data/system-design-visuals/7bb12746d2ff115b.json"},{"name":"Quorum reconciliation","summary":"Quorum reconciliation compares overlapping replica responses and repairs from the winning version set.","tradeoff":"Concurrent versions still need a merge rule.","visualPath":"../assets/data/system-design-visuals/4eb8d1bc2bbaccf5.json"}]},{"title":"Consistency contracts","concepts":[{"name":"Causal consistency","summary":"Causal consistency preserves happened-before relationships while allowing concurrent updates.","tradeoff":"Clients and replicas carry causal metadata.","visualPath":"../assets/data/system-design-visuals/b9493a9c627eab1a.json"},{"name":"Strong consistency","summary":"Strong consistency exposes a single authoritative view according to a defined ordering contract.","tradeoff":"Coordination raises latency and reduces partition availability.","visualPath":"../assets/data/system-design-visuals/57e060a224e78cb7.json"},{"name":"Eventual consistency","summary":"Eventual consistency guarantees replica convergence after updates stop and propagation succeeds.","tradeoff":"It gives no useful staleness bound alone.","visualPath":"../assets/data/system-design-visuals/11fbea8cf4538a21.json"}]}]},{"id":"distributed-deduplication-idempotency","title":"Distributed Deduplication & Idempotency","intro":"Make retries and duplicate delivery produce one durable business outcome.","groups":[{"title":"Request identity","concepts":[{"name":"Idempotency keys","summary":"Idempotency keys bind retries of one logical command to a durable stored outcome.","tradeoff":"Scope and retention must be explicit.","visualPath":"../assets/data/system-design-visuals/ea044f354b7a57b9.json"},{"name":"Request fingerprints","summary":"Request fingerprints detect reuse of one idempotency key for different payload intent.","tradeoff":"Canonicalization can be difficult.","visualPath":"../assets/data/system-design-visuals/6556c408fe100057.json"},{"name":"Deduplication tables","summary":"Deduplication tables persist processed identities with unique constraints and outcome state.","tradeoff":"They require partitioning and cleanup.","visualPath":"../assets/data/system-design-visuals/6e47381e8eca2304.json"},{"name":"Sequence numbers","summary":"Sequence numbers identify order and duplicates within a producer or entity stream.","tradeoff":"Producer failover must preserve epochs and progress.","visualPath":"../assets/data/system-design-visuals/5e20262ce21be8cf.json"},{"name":"Event IDs","summary":"Event IDs provide stable identity across publication retries, relays, and replays.","tradeoff":"Derived events need clear identity lineage.","visualPath":"../assets/data/system-design-visuals/1ac10c733498468d.json"}]},{"title":"Delivery semantics","concepts":[{"name":"Exactly-once illusion","summary":"The exactly-once illusion comes from hiding retries inside a bounded transaction while external effects remain ambiguous.","tradeoff":"End-to-end physical execution can still repeat.","visualPath":"../assets/data/system-design-visuals/230eb79d2104366b.json"},{"name":"At-least-once + idempotency","summary":"At-least-once + idempotency retries until delivery while making repeated effects harmless.","tradeoff":"Idempotency state adds storage and coordination.","visualPath":"../assets/data/system-design-visuals/221bb6776bdd7d2c.json"},{"name":"Idempotent consumers","summary":"Idempotent consumers atomically record message identity with the resulting local state change.","tradeoff":"Processed identity retention must cover replay.","visualPath":"../assets/data/system-design-visuals/2255ba371b58a864.json"},{"name":"Transactional deduplication","summary":"Transactional deduplication commits the dedup record and business effect in one atomic transaction.","tradeoff":"It is usually limited to one transactional store.","visualPath":"../assets/data/system-design-visuals/22e19aa4695ce34f.json"}]},{"title":"Distributed state","concepts":[{"name":"Distributed dedup caches","summary":"Distributed dedup caches share recent identities across instances for fast duplicate checks.","tradeoff":"Eviction and inconsistency can admit duplicates.","visualPath":"../assets/data/system-design-visuals/449dfe07b0c2c73f.json"}]}]},{"id":"time-based-distributed-patterns","title":"Time-Based Distributed Patterns","intro":"Treat time as an uncertain input and make windows, expiry, and scheduling semantics explicit.","groups":[{"title":"Retention and partitioning","concepts":[{"name":"TTL","summary":"TTL defines how long a record or cache entry remains valid or retained.","tradeoff":"Deletion is often asynchronous after logical expiry.","visualPath":"../assets/data/system-design-visuals/2bef43bc7a0ce8b1.json"},{"name":"Expiration","summary":"Expiration transitions state based on a time boundary with explicit visibility and cleanup behavior.","tradeoff":"Clock skew can move the boundary.","visualPath":"../assets/data/system-design-visuals/620292ffd05b9ba6.json"},{"name":"Time buckets","summary":"Time buckets group records or counters into fixed intervals for bounded storage and queries.","tradeoff":"Boundary effects complicate rolling calculations.","visualPath":"../assets/data/system-design-visuals/a0fadda1f511a26e.json"},{"name":"Time-based partitioning","summary":"Time-based partitioning places data by time range for efficient retention and range scans.","tradeoff":"Current partitions can become write hotspots.","visualPath":"../assets/data/system-design-visuals/f5fd9ca0a773a66d.json"}]},{"title":"Windows and stream time","concepts":[{"name":"Sliding windows","summary":"Sliding windows continuously aggregate overlapping time ranges.","tradeoff":"Overlap increases state and computation.","visualPath":"../assets/data/system-design-visuals/e46186acee8c6a4a.json"},{"name":"Tumbling windows","summary":"Tumbling windows divide time into adjacent non-overlapping intervals.","tradeoff":"Events near boundaries may split one real-world burst.","visualPath":"../assets/data/system-design-visuals/126f17e266f917e1.json"},{"name":"Watermarks","summary":"Watermarks estimate event-time completeness and trigger results despite out-of-order arrival.","tradeoff":"Aggressive watermarks require more corrections.","visualPath":"../assets/data/system-design-visuals/79d3ea5f47cba2b8.json"},{"name":"Event time","summary":"Event time is when an event occurred at its source.","tradeoff":"Source timestamps may be late or inaccurate.","visualPath":"../assets/data/system-design-visuals/e78202d73df662c1.json"},{"name":"Processing time","summary":"Processing time is when the system observes or computes over an event.","tradeoff":"Results vary with delays and replays.","visualPath":"../assets/data/system-design-visuals/6adcc039a17d9097.json"}]},{"title":"Coordination and scheduling","concepts":[{"name":"Leases","summary":"Leases grant time-bounded ownership that must be renewed and fenced.","tradeoff":"Pauses and skew can create overlapping beliefs.","visualPath":"../assets/data/system-design-visuals/bf51898145b7b5b0.json"},{"name":"Heartbeats","summary":"Heartbeats provide periodic evidence of liveness or progress.","tradeoff":"A missed heartbeat proves suspicion, not failure.","visualPath":"../assets/data/system-design-visuals/2aadd78935c01e1b.json"},{"name":"Delayed queues","summary":"Delayed queues hide work until a not-before time, then expose it for idempotent execution.","tradeoff":"Strict timing precision is expensive.","visualPath":"../assets/data/system-design-visuals/08c822753ce172cf.json"},{"name":"Scheduled execution","summary":"Scheduled execution persists job identity, due time, attempts, and outcome across failover.","tradeoff":"Exactly-once wall-clock execution is not guaranteed.","visualPath":"../assets/data/system-design-visuals/09f9f60bc296c945.json"},{"name":"Clock skew","summary":"Clock skew is the difference between clocks and must be bounded or avoided in correctness decisions.","tradeoff":"Synchronization never removes all uncertainty.","visualPath":"../assets/data/system-design-visuals/0e949d36219fbdf6.json"},{"name":"Logical clocks","summary":"Logical clocks order events from causality rather than relying on physical timestamps.","tradeoff":"They do not measure real elapsed time.","visualPath":"../assets/data/system-design-visuals/f2c42b5567d82fe7.json"}]}]},{"id":"advanced-senior-staff-level-concepts","title":"Advanced / Senior-Staff-Level Concepts","intro":"Connect distributed theory, resilience, scale, and operational design across the whole system.","groups":[{"title":"Topology and placement","concepts":[{"name":"Cell-based architecture","summary":"Cell-based architecture deploys self-contained slices of compute and data for bounded failure and scaling.","tradeoff":"Cells duplicate infrastructure and complicate global features.","visualPath":"../assets/data/system-design-visuals/ae20305e7bcca1fa.json"},{"name":"Shuffle sharding","summary":"Shuffle sharding assigns each tenant a small random subset of workers to limit shared fate.","tradeoff":"Capacity planning and rebalancing become harder.","visualPath":"../assets/data/system-design-visuals/f28b92f04049039f.json"},{"name":"Consistent hashing","summary":"Consistent hashing maps keys around a ring so membership changes move limited data.","tradeoff":"Virtual nodes are needed for good balance.","visualPath":"../assets/data/system-design-visuals/6e4d55372e052618.json"},{"name":"Rendezvous hashing","summary":"Rendezvous hashing scores each key-node pair and selects the highest-scoring owners.","tradeoff":"Naive selection evaluates every node.","visualPath":"../assets/data/system-design-visuals/a02f49a608596793.json"},{"name":"Gossip protocols","summary":"Gossip protocols spread membership and state probabilistically through peer exchanges.","tradeoff":"Convergence is eventual and messages are redundant.","visualPath":"../assets/data/system-design-visuals/032a6a5cf7cd5e7c.json"},{"name":"Merkle trees","summary":"Merkle trees compare hierarchical hashes to locate replica divergence efficiently.","tradeoff":"Tree maintenance consumes resources.","visualPath":"../assets/data/system-design-visuals/5ea6f89e004b528b.json"}]},{"title":"Convergence and ordering","concepts":[{"name":"CRDTs","summary":"CRDTs use mergeable state or commutative operations to converge without coordination.","tradeoff":"Metadata and supported invariants can be limiting.","visualPath":"../assets/data/system-design-visuals/ec16dc8b878c59bf.json"},{"name":"Vector clocks","summary":"Vector clocks identify causal order and concurrency among distributed versions.","tradeoff":"Vectors grow with participants.","visualPath":"../assets/data/system-design-visuals/dabb35fe24625f8b.json"},{"name":"Hybrid logical clocks","summary":"Hybrid logical clocks combine physical time with logical counters for causal, readable timestamps.","tradeoff":"Large clock offsets still need handling.","visualPath":"../assets/data/system-design-visuals/6c160367a1de7488.json"},{"name":"Quorum systems","summary":"Quorum systems use intersecting replica subsets to preserve evidence across reads, writes, or decisions.","tradeoff":"Quorum loss stops progress.","visualPath":"../assets/data/system-design-visuals/8f9a41594b0b2c1a.json"},{"name":"Consensus","summary":"Consensus makes replicas agree on one ordered decision history despite crash failures.","tradeoff":"It adds latency and needs a quorum.","visualPath":"../assets/data/system-design-visuals/01d68833a2c6437e.json"},{"name":"Paxos","summary":"Paxos uses ballots and intersecting quorums to choose values safely.","tradeoff":"Implementation and operation are subtle.","visualPath":"../assets/data/system-design-visuals/0b9445bb40737de0.json"},{"name":"Raft","summary":"Raft uses terms, leader election, and replicated logs to implement understandable consensus.","tradeoff":"The leader can bottleneck writes.","visualPath":"../assets/data/system-design-visuals/ffdc4441f223a0ae.json"},{"name":"Fencing tokens","summary":"Fencing tokens are increasing epochs that resources use to reject stale owners.","tradeoff":"Every protected write path must enforce them.","visualPath":"../assets/data/system-design-visuals/56d9b359855c6d79.json"},{"name":"Leases","summary":"Leases provide renewable time-bounded authority, normally paired with fencing.","tradeoff":"Time alone cannot prevent stale writes safely.","visualPath":"../assets/data/system-design-visuals/f53d93db725d9fc4.json"}]},{"title":"Transactions and state models","concepts":[{"name":"Idempotency","summary":"Idempotency makes repeated execution converge on the same intended state.","tradeoff":"Repeated external side effects still need deduplication.","visualPath":"../assets/data/system-design-visuals/8e11d5809c324a76.json"},{"name":"Exactly-once semantics","summary":"Exactly-once semantics combine transactional progress and deterministic identity within a stated boundary.","tradeoff":"The guarantee rarely spans external systems.","visualPath":"../assets/data/system-design-visuals/825cdc656d20cfcd.json"},{"name":"Transactional outbox","summary":"A transactional outbox commits business state and outgoing intent in one local transaction.","tradeoff":"Publishing remains at least once.","visualPath":"../assets/data/system-design-visuals/8b7bc19b54a7c1a6.json"},{"name":"Sagas","summary":"Sagas coordinate local transactions with durable progress and semantic compensation.","tradeoff":"Intermediate states are externally visible.","visualPath":"../assets/data/system-design-visuals/6fbdf2c068da4ea1.json"},{"name":"Event sourcing","summary":"Event sourcing stores immutable domain facts and derives current state through replay.","tradeoff":"Evolution, deletion, and replay are complex.","visualPath":"../assets/data/system-design-visuals/d8b322a01f8e68b0.json"},{"name":"CQRS","summary":"CQRS separates command and query models when their invariants or scaling differ.","tradeoff":"Projection lag and duplicate models add complexity.","visualPath":"../assets/data/system-design-visuals/c40994dd0eec8be7.json"}]},{"title":"Overload and latency","concepts":[{"name":"Backpressure","summary":"Backpressure signals producers to slow when downstream capacity is saturated.","tradeoff":"Pressure can propagate across dependencies.","visualPath":"../assets/data/system-design-visuals/708a5c2097a92587.json"},{"name":"Load shedding","summary":"Load shedding rejects lower-value work early to preserve critical capacity.","tradeoff":"It deliberately reduces served traffic.","visualPath":"../assets/data/system-design-visuals/a785682e85ad20cd.json"},{"name":"Hedged requests","summary":"Hedged requests issue a delayed duplicate and use the first valid response to reduce tail latency.","tradeoff":"They consume extra capacity and require idempotency.","visualPath":"../assets/data/system-design-visuals/01e596b9559334da.json"},{"name":"Adaptive throttling","summary":"Adaptive throttling adjusts admission from observed latency, errors, and saturation.","tradeoff":"Feedback loops can oscillate.","visualPath":"../assets/data/system-design-visuals/2697de2ca8644ae0.json"},{"name":"Cache stampede prevention","summary":"Cache stampede prevention coalesces refreshes, jitters expiry, or serves bounded stale data.","tradeoff":"Coordination and stale serving complicate caches.","visualPath":"../assets/data/system-design-visuals/57e41b2233166d17.json"},{"name":"Hot-key mitigation","summary":"Hot-key mitigation uses replication, coalescing, salting, or isolation to spread skewed demand.","tradeoff":"Splitting keys complicates ordering and aggregation.","visualPath":"../assets/data/system-design-visuals/2857caf76a856996.json"},{"name":"Approximate data structures","summary":"Approximate data structures trade bounded error for compact, fast membership or frequency estimates.","tradeoff":"False positives or estimation error affect decisions.","visualPath":"../assets/data/system-design-visuals/52dc35fbdf60fd07.json"}]},{"title":"Streaming and snapshots","concepts":[{"name":"Stream processing","summary":"Stream processing continuously transforms ordered partitions while checkpointing state and progress.","tradeoff":"Cross-partition ordering and state recovery are complex.","visualPath":"../assets/data/system-design-visuals/feb628f2bef792e6.json"},{"name":"Watermarks","summary":"Watermarks estimate event-time progress so stream processors can close windows.","tradeoff":"Late events require updates, retractions, or drops.","visualPath":"../assets/data/system-design-visuals/53168a40ff0f8145.json"},{"name":"Distributed snapshots","summary":"Distributed snapshots capture a consistent global cut without stopping all participants.","tradeoff":"In-flight messages and channel state must be represented.","visualPath":"../assets/data/system-design-visuals/a788d7bb51f624ac.json"}]},{"title":"Global resilience and architecture","concepts":[{"name":"Multi-region active-active","summary":"Multi-region active-active serves writes from multiple regions for locality and regional resilience.","tradeoff":"Conflicts and cross-region invariants become harder.","visualPath":"../assets/data/system-design-visuals/1ec5cb651574b575.json"},{"name":"Conflict resolution","summary":"Conflict resolution selects or merges concurrent state using deterministic domain rules.","tradeoff":"Automatic convergence may lose business intent.","visualPath":"../assets/data/system-design-visuals/fd89b59b54b73767.json"},{"name":"Disaster recovery","summary":"Disaster recovery restores service and data to explicit RTO and RPO through practiced procedures.","tradeoff":"Tighter objectives cost more capacity and coordination.","visualPath":"../assets/data/system-design-visuals/d06608b669cc4427.json"},{"name":"Cell isolation","summary":"Cell isolation prevents traffic, data, and failures from freely crossing cell boundaries.","tradeoff":"Isolation reduces resource pooling.","visualPath":"../assets/data/system-design-visuals/5890fe1ce941967d.json"},{"name":"Blast-radius management","summary":"Blast-radius management bounds failures through cells, quotas, rings, credentials, and staged changes.","tradeoff":"More boundaries increase operating cost.","visualPath":"../assets/data/system-design-visuals/4e208239b680dd10.json"},{"name":"Control plane / data plane separation","summary":"Control plane / data plane separation keeps orchestration failures from directly stopping established serving paths.","tradeoff":"Serving must tolerate stale configuration.","visualPath":"../assets/data/system-design-visuals/e00724270dd43369.json"},{"name":"Data plane scalability","summary":"Data plane scalability partitions high-volume serving work horizontally with local fast paths.","tradeoff":"Global coordination undermines scale.","visualPath":"../assets/data/system-design-visuals/b515745a8deb6786.json"},{"name":"Control plane consistency","summary":"Control plane consistency ensures configuration changes are ordered, durable, and auditable before broad application.","tradeoff":"Stronger consistency slows management operations.","visualPath":"../assets/data/system-design-visuals/6b0125aef37bcd88.json"}]}]}];
